            if (!p) continue;
            if ((buf + "\n" + p).length > 700) {
                if (buf) out.push(buf);
                buf = p;
            } else {
                buf = buf ? buf + "\n" + p : p;
            }
        }
        if (buf) out.push(buf);
        return out;
