function parseBocaiApiSiteText(raw) {
    raw = String(raw || '').replace(/^\uFEFF/, '').trim();
    if (!raw) return null;
    var jsonStr = raw;
    var varMatch = raw.match(/(?:var|let|const)\s+\w+\s*=\s*([\s\S]*?);?\s*$/);
    if (varMatch) jsonStr = varMatch[1].trim();
    var parsed = JSON.parse(jsonStr);
    if (Array.isArray(parsed) && parsed.length > 0 && parsed[0].api_site) {
        return parsed[0].api_site;
    }
    if (parsed && parsed.api_site && !Array.isArray(parsed)) {
        return parsed.api_site;
    }
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
        var keys = Object.keys(parsed);
        var looksLikeApiSite = keys.length > 0;
        for (var i = 0; i < keys.length; i++) {
            var item = parsed[keys[i]];
            if (!item || typeof item !== 'object' || !(item.api || item.url)) {
                looksLikeApiSite = false;
                break;
            }
        }
        if (looksLikeApiSite) return parsed;
    }
    return null;
}

function importBocaiSitesFromText(raw) {
    var apiSite = parseBocaiApiSiteText(raw);
    if (!apiSite || typeof apiSite !== 'object') {
        return { ok: false, message: '无法识别配置格式，请检查内容', addCount: 0, skipCount: 0, invalidCount: 0 };
    }
    var keys = Object.keys(apiSite);
    if (keys.length === 0) {
        return { ok: false, message: '未发现有效的源数据', addCount: 0, skipCount: 0, invalidCount: 0 };
    }
    try {
        var cfg = getXjBase();
        if (!cfg.bocai_sites) cfg.bocai_sites = [];
        var existKeys = {};
        var existEnabledCount = 0;
        for (var i = 0; i < cfg.bocai_sites.length; i++) {
            existKeys[cfg.bocai_sites[i].key] = true;
            if (cfg.bocai_sites[i].enabled !== false) existEnabledCount++;
        }
        var maxEnabled = parseInt(getItem('xj_bocai_max_enabled', '5'));
        if (isNaN(maxEnabled) || maxEnabled < 1) maxEnabled = 5;
        var addCount = 0;
        var skipCount = 0;
        var invalidCount = 0;
        for (var j = 0; j < keys.length; j++) {
            var k = String(keys[j] || '').trim();
            if (!k) { invalidCount++; continue; }
            if (existKeys[k]) { skipCount++; continue; }
            var s = apiSite[keys[j]];
            if (!s || typeof s !== 'object') { invalidCount++; continue; }
            var api = String(s.api || s.url || '').trim();
            if (!api) { invalidCount++; continue; }
            var newEnabled = existEnabledCount < maxEnabled;
            cfg.bocai_sites.push({
                key: k,
                name: s.name || k,
                api: api,
                detail: s.detail || '',
                enabled: newEnabled
            });
            existKeys[k] = true;
            if (newEnabled) existEnabledCount++;
            addCount++;
        }
        saveXjBase(cfg);
        return { ok: true, addCount: addCount, skipCount: skipCount, invalidCount: invalidCount };
    } catch (e) {
        return { ok: false, message: '导入失败: ' + e.message, addCount: 0, skipCount: 0, invalidCount: 0 };
    }
}

function speedTestBocaiSites() {
    var sites = getBocaiSites();
    var requests = [];
    var reqIndex = [];
    var results = [];
    for (var i = 0; i < sites.length; i++) {
        var site = sites[i];
        if (site.name.indexOf('🔞') !== -1) {
            results.push({key: site.key, time: 99999, name: site.name, skipped: true});
            continue;
        }
        reqIndex.push({idx: results.length, site: site, start: Date.now()});
        results.push({key: site.key, time: 99999, name: site.name});
        requests.push({
            url: site.api + '?ac=detail&wd=你好',
            options: {timeout: 5000, headers: {'User-Agent': 'Mozilla/5.0'}}
        });
    }
    if (requests.length > 0 && (typeof batchFetch === 'function' || typeof bf === 'function')) {
        try {
            var fetcher = typeof batchFetch === 'function' ? batchFetch : bf;
            var bodies = fetcher(requests);
            for (var r = 0; r < reqIndex.length; r++) {
                var body = bodies && bodies[r] ? bodies[r] : '';
                var elapsed = Date.now() - reqIndex[r].start;
                try {
                    var json = JSON.parse(body);
                    var count = (json && json.list) ? json.list.length : 0;
                    results[reqIndex[r].idx].time = count > 0 ? elapsed : 99999;
                } catch (e) {
                    results[reqIndex[r].idx].time = 99999;
                }
            }
        } catch (e2) {
            for (var s = 0; s < reqIndex.length; s++) {
                var start = Date.now();
                try {
                    var resp = fetch(reqIndex[s].site.api + '?ac=detail&wd=你好', {timeout: 5000, headers: {'User-Agent': 'Mozilla/5.0'}});
                    var json2 = JSON.parse(resp);
                    var count2 = (json2 && json2.list) ? json2.list.length : 0;
                    results[reqIndex[s].idx].time = count2 > 0 ? (Date.now() - start) : 99999;
                } catch (e3) {}
            }
        }
    } else {
        for (var j = 0; j < reqIndex.length; j++) {
            var start2 = Date.now();
            try {
                var resp2 = fetch(reqIndex[j].site.api + '?ac=detail&wd=你好', {timeout: 5000, headers: {'User-Agent': 'Mozilla/5.0'}});
                var json3 = JSON.parse(resp2);
                var count3 = (json3 && json3.list) ? json3.list.length : 0;
                results[reqIndex[j].idx].time = count3 > 0 ? (Date.now() - start2) : 99999;
            } catch (e4) {}
        }
    }
    results.sort(function(a, b) { return a.time - b.time; });
    var maxCfg = parseInt(getItem('xj_bocai_max_enabled', '5'));
    if (isNaN(maxCfg) || maxCfg < 0) maxCfg = 5;
    var maxEnabled = maxCfg === 0 ? results.length : Math.min(maxCfg, results.length);
    var topKeys = [];
    for (var t = 0; t < maxEnabled; t++) {
        if (!results[t].skipped) topKeys.push(results[t].key);
    }
    var cfg = getXjBase();
    var list = cfg.bocai_sites || [];
    for (var k = 0; k < list.length; k++) {
        list[k].enabled = topKeys.indexOf(list[k].key) !== -1;
    }
    var topItems = [];
    var restItems = [];
    for (var n = 0; n < list.length; n++) {
        if (topKeys.indexOf(list[n].key) !== -1) topItems.push(list[n]);
        else restItems.push(list[n]);
    }
    cfg.bocai_sites = topItems.concat(restItems);
    saveXjBase(cfg);
    var msg = '批量测速完成，结果如下：\n\n';
    for (var m = 0; m < results.length; m++) {
        var timeStr = results[m].skipped ? '⏭已跳过' : (results[m].time >= 99999 ? '超时/无结果' : results[m].time + 'ms');
        var flag = results[m].skipped ? '🔞跳过' : (topKeys.indexOf(results[m].key) !== -1 ? '✅开启' : '❌关闭');
        msg += flag + ' ' + results[m].name + '：' + timeStr + '\n';
    }
    return msg;
}

