function cnToNum(cn) {
    var cnMap = {'零':0,'一':1,'二':2,'三':3,'四':4,'五':5,'六':6,'七':7,'八':8,'九':9,'十':10,'百':100,'千':1000};
    if (!cn) return 0;
    if (/^\d+$/.test(cn)) return parseInt(cn, 10);
    if (cn.length === 1 && cnMap[cn] !== undefined) return cnMap[cn];
    var r = 0, cur = 0;
    for (var i = 0; i < cn.length; i++) {
        var v = cnMap[cn[i]];
        if (v >= 10) { cur = cur === 0 ? v : cur * v; r += cur; cur = 0; }
        else cur = v;
    }
    r += cur;
    return r || 0;
}

function extractSeasonInfo(title) {
    var s = title || '';
    var m;
    m = s.match(/第([一二三四五六七八九十百千\d]+)[季部集期]/i);
    if (m) return { type: 'season', num: cnToNum(m[1]) };
    m = s.match(/([一二三四五六七八九十百千\d]+)[季部]/);
    if (m) return { type: 'season', num: cnToNum(m[1]) };
    m = s.match(/年番(\d*)/);
    if (m) return { type: 'nianfan', num: parseInt(m[1] || '0', 10) || 0 };
    m = s.match(/\bS(\d+)/i);
    if (m) return { type: 'season', num: parseInt(m[1], 10) };
    m = s.match(/剧场版/);
    if (m) return { type: '剧场版', num: 0 };
    m = s.match(/\b(OVA|OAD|SP)\b/i);
    if (m) return { type: m[1].toUpperCase(), num: 0 };
    m = s.match(/特别[篇编]|番外[篇编]?/);
    if (m) return { type: '特别篇', num: 0 };
    return null;
}

function matchSeasonInfo(searchName, resultName) {
    var a = extractSeasonInfo(searchName);
    var b = extractSeasonInfo(resultName);
    if (!a && !b) return true;
    if (!a) return true;  // 搜索词没有季节信息时，匹配所有结果
    if (!b) return false;
    if (a.type !== b.type) return false;
    return a.num === b.num;
}

function stripTitleTags(title) {
    return (title || '')
        .replace(/<[^>]+>/g, '')
        .replace(/&nbsp;/gi, '')
        .replace(/[【\[][^\]】]*(?:4K|8K|1080|720|2160|HDR|HD|臻彩|杜比|高码|中字|国语)[^\]】]*[\]】]/gi, '')
        .replace(/[（(][^）)]*(?:4K|8K|1080|720|2160|HDR|HD|臻彩|杜比|高码|中字|国语)[^）)]*[）)]/gi, '')
        .replace(/\s+/g, '')
        .trim();
}

function isCollectionTitle(title) {
    var s = stripTitleTags(title);
    return /全系列|合集|汇总|全集|附.{0,8}(前|全)?\d*季|前\d+季|总第[一二三四五六七八九十百千\d]+季/.test(s);
}

function isTargetTitle(movieName, resultTitle) {
    var title = stripTitleTags(resultTitle);
    if (!title) return false;
    var norm = normalizeTitle(movieName);
    var baseKey = normalizeSearchText(norm.baseName || norm.cleanName);
    var titleKey = normalizeSearchText(title);
    if (baseKey && titleKey.indexOf(baseKey) === -1) return false;
    if (norm.seasonInfo) {
        if (!matchSeasonInfo(movieName, title)) return false;
        if (isCollectionTitle(title)) return false;
    }
    return true;
}

function filterPanPlayUrlByTitle(playUrl, movieName) {
    if (!playUrl) return playUrl;
    var norm = normalizeTitle(movieName);
    var baseKey = normalizeSearchText(norm.baseName || norm.cleanName);
    if (!baseKey) return playUrl;
    var parts = playUrl.split('#').filter(function(e) { return e; });
    var kept = [];
    for (var i = 0; i < parts.length; i++) {
        var title = (parts[i].split('$')[0] || '').trim();
        var titleKey = normalizeSearchText(title);
        if (!titleKey || titleKey.indexOf(baseKey) === -1) continue;
        if (norm.seasonInfo && !matchSeasonInfo(movieName, title)) continue;
        if (norm.seasonInfo && isCollectionTitle(title)) continue;
        kept.push(parts[i]);
    }
    return kept.join('#');
}

function isPanAggResult(r) {
    if (!r) return false;
    if (r.type === 'pan' || r.type === 'pan_sub' || r._isPan || r.panType) return true;
    if (r.type === 'merged_rule' && r.sources && Array.isArray(r.sources)) {
        for (var i = 0; i < r.sources.length; i++) {
            var s = r.sources[i];
            if (s && (s.type === 'pan' || s.type === 'pan_sub' || s._isPan || s.panType)) return true;
        }
    }
    return false;
}

function filterAggResultsByTitle(results, movieName) {
    if (!results || !Array.isArray(results) || !movieName) return results;
    var out = [];
    for (var i = 0; i < results.length; i++) {
        var r = results[i];
        if (!r || !r.playUrl) {
            out.push(r);
            continue;
        }
        if (isPanAggResult(r)) {
            var filtered = filterPanPlayUrlByTitle(r.playUrl, movieName);
            if (!filtered) continue;
            var nr = JSON.parse(JSON.stringify(r));
            nr.playUrl = filtered;
            nr.epCount = filtered.split('#').filter(function(e) { return e; }).length;
            out.push(nr);
        } else {
            out.push(r);
        }
    }
    return out;
}

function buildBocaiTasks(movieName) {
    var apiSites = bocai_api()[0].api_site;
    var enabledKeys = getEnabledSiteKeys();
    var tasks = [];
    var norm = normalizeTitle(movieName);
    var searchName = norm.baseName || norm.cleanName;
    var cleanMovieName = norm.cleanName;
    for (var i = 0; i < enabledKeys.length; i++) {
        var key = enabledKeys[i];
        var site = apiSites[key];
        tasks.push({
            func: function(obj) {
                try {
                    var searchUrl = obj.api + '?ac=detail&wd=' + encodeURIComponent(obj.searchName);
                    var resp = fetch(searchUrl, { timeout: 12000, headers: { 'User-Agent': 'Mozilla/5.0' } });
                    var json = JSON.parse(resp);
                    if (json && json.list && json.list.length > 0) {
                        var seasonNum = (obj.seasonInfo && obj.seasonInfo.type === 'season') ? obj.seasonInfo.num : 0;
                        function nameOf(item) { return (item.vod_name || '').replace(/\s+/g, ''); }
                        function hasBase(n) { return n.indexOf(obj.baseName) >= 0; }
                        function seasonMark(n, num) {
                            if (!num) return false;
                            var cnMap = ['','一','二','三','四','五','六','七','八','九','十'];
                            var cn = cnMap[num] || '';
                            var pad = num < 10 ? ('0' + num) : String(num);
                            var reParts = ['S0*' + num + '(?!\\d)', '第\\s*' + num + '\\s*[季部]', num + '\\s*[季部]'];
                            if (cn) reParts.push('第\\s*' + cn + '\\s*[季部]', cn + '\\s*[季部]');
                            if (num === 1) reParts.push('S0*1(?!\\d)');
                            var re = new RegExp(reParts.join('|'), 'i');
                            return re.test(n) || n.indexOf('S' + pad) >= 0;
                        }
                        function isPureName(n) {
                            var stripped = n.replace(/S\d+/gi, '').replace(/第[一二三四五六七八九十百千\d]+[季部]/g, '').replace(/[一二三四五六七八九十百千\d]+[季部]/g, '');
                            return stripped.replace(/\s+/g, '') === obj.baseName;
                        }
                        var matched = null;
                        for (var j = 0; j < json.list.length; j++) {
                            if (nameOf(json.list[j]) === obj.cleanMovieName) { matched = json.list[j]; break; }
                        }
                        if (!matched && seasonNum >= 2) {
                            for (var j2 = 0; j2 < json.list.length; j2++) {
                                var n = nameOf(json.list[j2]);
                                if (hasBase(n) && seasonMark(n, seasonNum)) { matched = json.list[j2]; break; }
                            }
                        } else if (!matched && seasonNum === 1) {
                            for (var jS = 0; jS < json.list.length; jS++) {
                                var nS = nameOf(json.list[jS]);
                                if (hasBase(nS) && seasonMark(nS, 1)) { matched = json.list[jS]; break; }
                            }
                            if (!matched) {
                                for (var jP = 0; jP < json.list.length; jP++) {
                                    var nP = nameOf(json.list[jP]);
