        return '';
    }
}

function cleanDanmuKeyword(title) {
    var s = String(title || '');
    if (!s) return '';
    // 括号内清晰度/年份/标签
    s = s.replace(/[【\[\(（][^】\]\)）]*(?:4K|8K|1080P?|2160P?|720P?|HDR|HDR10|杜比|臻彩|高码|国语|粤语|日语|英语|中字|双语|港版|台版|抢先|未删减|导演剪辑|加长|无删减|Remastered|重制|修复|BluRay|WEB[- ]?DL|WEBRip|HDTV|BDRip|DVDRip)[^】\]\)）]*[】\]\)）]/gi, '');
    s = s.replace(/[【\[\(（]\s*(19|20)\d{2}\s*[】\]\)）]/g, '');
    // 副标题
    s = s.replace(/\s*[:：\-–—]\s*.+$/, '');
    // 季号 / Season / 第X季 / X季 / X部
    s = s.replace(/\bSeason\s*\d+\b/gi, '');
    s = s.replace(/\bS0*\d+(?:E0*\d+)?\b/gi, '');
    s = s.replace(/第\s*[一二三四五六七八九十百千0-9]+\s*[季部]/g, '');
    s = s.replace(/[一二三四五六七八九十0-9]+\s*[季部]/g, '');
    // 尾部年份
    s = s.replace(/\s*[\(（\[【]?\s*(19|20)\d{2}\s*[\)）\]】]?\s*$/, '');
    // 常见清晰度/语言尾标（未在括号里）
    s = s.replace(/\b(4K|8K|1080P?|2160P?|720P?|HDR|HDR10|杜比|臻彩|高码|国语|粤语|日语|英语|中字|双语|港版|台版|抢先|未删减|导演剪辑|加长|无删减|Remastered|重制|修复|BluRay|WEB[- ]?DL|WEBRip|HDTV|BDRip|DVDRip)\b/gi, '');
    // 全角空格 & 多空白
    s = s.replace(/\s+/g, ' ').trim();
    // 去掉首尾多余标点
    s = s.replace(/^[\s\-·•_,.。、]+|[\s\-·•_,.。、]+$/g, '');
    return s || String(title || '');
}

function getExternalDanmuUrl(playLink, title, fileName, episodeTitle) {
    var config = getExternalDanmuConfig();
    var dmLabel = config.mode === 'local' ? '本地弹幕' : '外接弹幕';
    try { log('【' + dmLabel + '调试】mode=' + config.mode + ' sources=' + config.sources.length + ' title=' + (title || '') + ' fileName=' + (fileName || '') + ' episode=' + (episodeTitle || '')); } catch (e) {}
    if (config.mode !== 'external' && config.mode !== 'local') return '';
    var base;
    if (config.mode === 'local') {
        base = 'http://localhost:9321';
        try {
            var test = JSON.parse(fetch(base + '/api/config', {timeout: 2000}) || '{}');
            if (!test || !test.repository || test.repository.indexOf('danmu_api') < 0) return '';
        } catch(e) { return ''; }
    } else {
        if (config.sources.length === 0) return '';
        base = config.sources[0].url.replace(/\/$/, '');
    }
    if (fileName) {
        var matchText = fileName + (config.platform ? ' @' + config.platform : '');
        try {
            var matchedRaw = fetch(base + '/api/v2/match', { method: 'POST', body: JSON.stringify({ fileName: matchText }), headers: { 'Content-Type': 'application/json' }, timeout: config.timeout }) || '';
            var matched = JSON.parse(matchedRaw || '{}');
            try { log('【' + dmLabel + '文件匹配】keyword=' + matchText + ' matches=' + ((matched.matches || []).length)); } catch (e) {}
            if (matched.matches && matched.matches[0] && matched.matches[0].episodeId) return saveExternalDanmuJson(base + '/api/v2/comment/' + matched.matches[0].episodeId + '?format=json', config, matched.matches[0].episodeId);
        } catch (e) { try { log('【' + dmLabel + '文件匹配异常】' + e.message); } catch (ignore) {} }
    } else if (/^https?:\/\/(?:[^/]+\.)?(?:iqiyi\.com|v\.qq\.com|youku\.com|mgtv\.com|bilibili\.com|miguvideo\.com|sohu\.com|le\.com|pptv\.com)\//i.test(playLink || '')) {
        try { log('【' + dmLabel + '官方链接】' + playLink); } catch (e) {}
        return saveExternalDanmuJson(base + '/api/v2/comment?url=' + encodeURIComponent(playLink) + '&format=json', config, encodeURIComponent(playLink));
    } else if (title) {
        var episodeMatch = String(episodeTitle || '').match(/(?:第\s*)?(\d+)(?:\s*[集话期章])?/);
        var episode = episodeMatch ? String(parseInt(episodeMatch[1], 10)) : (episodeTitle || '');
        var searchAnime = cleanDanmuKeyword(title);
        try {
            var searchUrl = base + '/api/v2/search/episodes?anime=' + encodeURIComponent(searchAnime) + (episode ? '&episode=' + encodeURIComponent(episode) : '');
            var searchRaw = fetch(searchUrl, { timeout: config.timeout }) || '';
            try { log('【' + dmLabel + '搜索响应】url=' + searchUrl + ' length=' + searchRaw.length + ' body=' + searchRaw.substring(0, 200)); } catch (e) {}
            var searchData = JSON.parse(searchRaw || '{}');
            var candidates = [];
            (searchData.animes || []).forEach(function(anime) { (anime.episodes || []).forEach(function(ep) { candidates.push(ep); }); });
            if (config.platform) {
                var preferred = candidates.filter(function(ep) { return String(ep.episodeTitle || '').toLowerCase().indexOf(config.platform.toLowerCase()) >= 0; });
                if (preferred.length) candidates = preferred;
            }
            try { log('【' + dmLabel + '剧集搜索】title=' + title + ' anime=' + searchAnime + ' episode=' + episode + ' matches=' + candidates.length); } catch (e) {}
            if (candidates[0] && candidates[0].episodeId) return saveExternalDanmuJson(base + '/api/v2/comment/' + candidates[0].episodeId + '?format=json', config, candidates[0].episodeId);
        } catch (e) { try { log('【' + dmLabel + '剧集搜索异常】' + e.message); } catch (ignore) {} }
    }
    try { log('【' + dmLabel + '结果】未匹配到弹幕'); } catch (e) {}
    return '';
}

