        }
    }
    if (dmPath) log('弹幕获取完毕[' + (dmSource || '弹幕盒子') + ']');

    if (enabledParse.length === 0) {
        if (parses.length === 0) {
            return 'toast://⚠️ 未配置解析接口，请先在解析管理页面添加解析';
        }
        return JSON.stringify({
            names: ["默认嗅探"],
            urls: ["video://" + playLink + "#isVideo=true#"],
            danmu: dmPath,
            headers: [defaultHeaders]
        });
    }

    function extractUserJs(jsCode) {
        if (!jsCode || !jsCode.trim()) return "";
        try {
            var parsed = JSON.parse(jsCode);
            if (parsed.js) return parsed.js;
        } catch (e) {}
        return jsCode;
    }

    var names = [];
    var urls = [];
    var headers = [];
    var extras = [];

    for (var i = 0; i < enabledParse.length; i++) {
        var p = enabledParse[i];

        if (p.type === "X") {
            names.push(p.name + " [W]");
            urls.push("video://" + p.url + playLink + "#isVideo=true#");
            headers.push(defaultHeaders);
            extras.push({
                blockRules: ['*.png', '*.jpg', '*.gif', '*.css', '*ads*'],
                cacheM3u8: true
            });
            continue;
        }

        if (p.type === "J") {
            var userJs = extractUserJs(p.jsCode || "");
            if (!userJs) continue;
            names.push(p.name + " [JS]");
            urls.push("webRule://" + p.url + playLink + "#isVideo=true#@" + userJs);
            headers.push(defaultHeaders);
            extras.push({
                blockRules: ['*.png', '*.jpg', '*.gif', '*.css', '*ads*'],
                cacheM3u8: true
            });
            continue;
        }

        if (p.type === "Z") {
            try {
                var res = fetch(p.url + playLink);
                if (!res || res.trim() === '') continue;
                var json = JSON.parse(res);
                var val = null;
                if (p.Names && p.Names.trim()) {
                    val = p.Names.split('.').reduce(function(obj, key) {
                        return (obj && obj[key] ? obj[key] : null);
                    }, json);
                }
                if (!val) val = json.url;
                if (typeof val !== 'string' || !val.trim()) continue;
                var directUrl = val.trim().startsWith('//') ? 'https:' + val.trim() : val.trim();
                if (!directUrl.startsWith('http')) continue;

                var isYouku = (json.msg && json.msg.includes('优酷直连')) || isYoukuDirectLink(directUrl);
                var isM3u8 = directUrl.includes('m3u8');
                var finalUrlToPlay = directUrl;
                var finalHeaders = defaultHeaders;

                if (isYouku && isM3u8) {
                    var youkuHeaders = {
                        'User-Agent': 'Mozilla/5.0 (Linux; Android 12; SM-G998B) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/116.0.5845.92 Mobile Safari/537.36 YKApp/9.8.0 (Youku)',
                        'Referer': playLink
                    };
                    try {
                        var randomFileName = 'm3u8_' + Date.now() + '_' + Math.random().toString(36).substring(2) + '.m3u8';
                        var cachedPath = cacheM3u8(directUrl, youkuHeaders, randomFileName);
                        if (cachedPath && cachedPath.startsWith('file://')) {
                            finalUrlToPlay = cachedPath.split('##')[0];
                            finalHeaders = {};
                        } else {
                            finalHeaders = youkuHeaders;
                        }
                    } catch (e) {
                        finalHeaders = youkuHeaders;
                    }
                }

                var playerUrl;
                if (finalUrlToPlay.startsWith('file://') && isM3u8) {
                    playerUrl = "video://" + finalUrlToPlay + "#isVideo=true#";
                } else {
                    playerUrl = finalUrlToPlay + '#original=' + encodeURIComponent(playLink) + "&url=" + playLink;
                }

                names.push(p.name + " [解]");
                urls.push(playerUrl);
                headers.push(finalHeaders);
                extras.push({});
            } catch (e) {
                log('【JSON直链】解析失败: ' + e.message);
                continue;
            }
            continue;
        }
    }

    if (names.length === 0) {
        return JSON.stringify({
            names: ["默认嗅探"],
            urls: ["video://" + playLink + "#isVideo=true#"],
            danmu: dmPath,
            headers: [defaultHeaders],
            extras: [{}]
        });
    }

    return JSON.stringify({
        names: names,
        urls: urls,
        danmu: dmPath,
        headers: headers,
        extras: extras
    });
}

