function renderPagination(d, objId, markerPrefix, totalPages, currentPage, sortOrder, totalItems) {
    if (totalPages <= 1) return;
    var epOrderKey = markerPrefix + '_order_' + objId;
    var epPageKey = markerPrefix + '_ep_page_' + objId;
    var orderLabel = sortOrder === 'desc' ? '倒序' : '正序';
    var pageSize = getPageSize();
    var hasPrev = currentPage > 0;
