    d.push({ title: hasPrev ? '上一页' : '.', col_type: 'text_4', url: hasPrev ? $('#noLoading#').lazyRule(function(key, cur) { putMyVar(key, String(cur - 1)); refreshPage(false); return 'hiker://empty'; }, epPageKey, currentPage) : 'hiker://empty', extra: { cls: markerPrefix + '_ep', id: markerPrefix + '_pagination' } });
