    d.push({ title: hasNext ? '下一页' : '.', col_type: 'text_4', url: hasNext ? $('#noLoading#').lazyRule(function(key, cur) { putMyVar(key, String(cur + 1)); refreshPage(false); return 'hiker://empty'; }, epPageKey, currentPage) : 'hiker://empty', extra: { cls: markerPrefix + '_ep' } });
    if (totalPages > 1) {
        for (var pi = 0; pi < totalPages; pi++) {
            var rangeStart = pi * pageSize + 1;
