    baseName = baseName.replace(/[季部集期]\d+/g, '');
    baseName = baseName.replace(/年番\d*/g, '');
    baseName = baseName.replace(/\bS\d+\s*(E\d+)?\b/gi, '');
    baseName = baseName.replace(/剧场版/g, '');
    baseName = baseName.replace(/OVA|OAD|SP/gi, '');
    baseName = baseName.replace(/特别[篇编]/g, '');
