            var code = aesDecode('Qingdou', strs[i].split('￥')[1]);
            var text;
            if (/^http|^云/.test(code)) {
                text = parsePaste(code);
            } else {
                text = code;
            }
            if (text && !/^error/.test(text)) {
                var gzip = $.require("gzip.js");
                var sharetxt = gzip.unzip(text);
                var imports = JSON.parse(sharetxt);
                for (var j = 0; j < imports.length; j++) {
