function qdDoImport(importdatas, mode) {
    var cfg = getXjBase();
    if (!cfg.parses) cfg.parses = [];
    if (!cfg.bocai_sites) cfg.bocai_sites = [];
    var baseDirty = false;
    for (var i = 0; i < importdatas.length; i++) {
        var it = importdatas[i];
        if (it._xj_type === 'parse') {
            var exists = -1;
            for (var j = 0; j < cfg.parses.length; j++) {
                if (cfg.parses[j].name === it.name && cfg.parses[j].url === it.url) { exists = j; break; }
            }
            if (mode === 1 && exists >= 0) {
                var newItem = JSON.parse(JSON.stringify(it));
                delete newItem._xj_type;
                cfg.parses[exists] = newItem;
                baseDirty = true;
            } else if (exists < 0) {
                var newItem = JSON.parse(JSON.stringify(it));
                delete newItem._xj_type;
                cfg.parses.push(newItem);
                baseDirty = true;
            }
        } else if (it._xj_type === 'bocai') {
            var exists = -1;
            for (var j = 0; j < cfg.bocai_sites.length; j++) {
                if (cfg.bocai_sites[j].key === it.key || cfg.bocai_sites[j].name === it.name) { exists = j; break; }
            }
            if (mode === 1 && exists >= 0) {
                var newItem = JSON.parse(JSON.stringify(it));
                delete newItem._xj_type;
                cfg.bocai_sites[exists] = newItem;
                baseDirty = true;
            } else if (exists < 0) {
                var newItem = JSON.parse(JSON.stringify(it));
                delete newItem._xj_type;
                cfg.bocai_sites.push(newItem);
                baseDirty = true;
            }
        } else if (it._xj_type === 'rule') {
            var cr = $.require("customRule");
            var rules = cr.getRuleList();
            var importName = String(it.name || '').replace(/^_fileSelect_/, '').trim();
            var isJarImport = it['类型'] === '本地包' || (it.api && String(it.api).indexOf('csp_') === 0) || !!it.jar;
            var exists = -1;
            if (isJarImport) {
                for (var j = 0; j < rules.length; j++) {
                    if (rules[j].name === importName || (it.key && rules[j].key === it.key)) { exists = j; break; }
                }
                var jarRuleData = {name: importName, '类型': '本地包', host: it.jar || it.host || '', api: it.api || '', jar: it.jar || '', ext: it.ext || '', enabled: it.enabled !== false};
                if (it.key) { jarRuleData.key = it.key; jarRuleData.id = it.id || ('jar_' + it.key); }
                else if (it.id) jarRuleData.id = it.id;
                if (mode === 1 && exists >= 0) {
                    jarRuleData.id = rules[exists].id;
                    cr.saveRule(jarRuleData);
                } else if (exists < 0) {
                    cr.saveRule(jarRuleData);
                }
            } else {
                var hm = (it.code || '').match(/["']?host["']?\s*[:=]\s*['"]([^'"]+)['"]/);
                var importHost = hm ? hm[1] : '';
                for (var j = 0; j < rules.length; j++) {
                    if (rules[j].name === importName || (importHost && rules[j].host === importHost)) { exists = j; break; }
                }
                var ruleType = it['类型'] || it['\u7c7b\u578b'] || '搜索源';
                var ruleData = {name: importName, '类型': ruleType, host: it.host || importHost, enabled: it.enabled !== false, code: it.code || ''};
                if (it.liveImportMode) ruleData.liveImportMode = it.liveImportMode;
                if (it.subscriptionUrl) ruleData.subscriptionUrl = it.subscriptionUrl;
                if (mode === 1 && exists >= 0) {
                    ruleData.id = rules[exists].id;
                    cr.saveRule(ruleData);
                } else if (exists < 0) {
                    cr.saveRule(ruleData);
                }
            }
        }
    }
    if (baseDirty) saveXjBase(cfg);
}

function qdGetImportPlan(importdatas) {
    importdatas = importdatas || [];
    var cfg = {};
    try { cfg = getXjBase(); } catch (e) { cfg = {}; }
    var parses = cfg.parses || [];
    var sites = cfg.bocai_sites || [];
    var rules = [];
    try { rules = $.require("customRule").getRuleList(); } catch(e2) {}
    var plan = { total: importdatas.length, add: 0, overwrite: 0, skip: 0, items: [] };
    for (var i = 0; i < importdatas.length; i++) {
        var it = importdatas[i] || {};
        var exists = -1;
        var typeLabel = it._xj_type === 'parse' ? '解析' : (it._xj_type === 'bocai' ? '菠菜' : '规则');
        if (it._xj_type === 'parse') {
            for (var p = 0; p < parses.length; p++) {
                if (parses[p].name === it.name && parses[p].url === it.url) { exists = p; break; }
            }
        } else if (it._xj_type === 'bocai') {
            for (var b = 0; b < sites.length; b++) {
                if (sites[b].key === it.key || sites[b].name === it.name) { exists = b; break; }
            }
        } else if (it._xj_type === 'rule') {
            var isJarPlan = it['类型'] === '本地包' || (it.api && String(it.api).indexOf('csp_') === 0) || !!it.jar;
            if (isJarPlan) {
                for (var r = 0; r < rules.length; r++) {
                    if (rules[r].name === it.name || (it.key && rules[r].key === it.key)) { exists = r; break; }
                }
                typeLabel = '本地包';
            } else {
                var hm = (it.code || '').match(/["']?host["']?\s*[:=]\s*['"]([^'"]+)['"]/);
                var importHost = it.host || (hm ? hm[1] : '');
                for (var r = 0; r < rules.length; r++) {
                    if (rules[r].name === it.name || (importHost && rules[r].host === importHost)) { exists = r; break; }
                }
            }
        }
        var action = exists >= 0 ? 'overwrite' : 'add';
        if (action === 'add') plan.add++;
        else plan.overwrite++;
        plan.items.push({ index: i, data: it, typeLabel: typeLabel, action: action, exists: exists });
    }
    plan.skip = plan.overwrite;
    return plan;
}

function qdScanPyRisk(code) {
    var risks = [];
    var c = String(code || '');
    var patterns = [
        { re: /requests?\.(post|put)\s*\([^)]*['"]https?:\/\/(?!(127\.0\.0\.1|localhost))[^'"]*['"][^)]*['"]?(pass(word)?|pwd|token|sms|contacts?|sms|通讯录|短信|验证码)/i, msg: '疑似上传密码/验证码等敏感数据' },
        { re: /(android|java)\.content\.ContentResolver|getContentResolver\s*\(|android\.provider\.(ContactsContract|Telephony|CallLog)/i, msg: '疑似读取通讯录/短信/通话记录' },
        { re: /java\.io\.File\s*\(\s*['"]\/sdcard|\/storage\/emulated\/0(?!\/Android\/data)/, msg: '疑似扫描设备存储文件' },
        { re: /(android\.content\.pm|getInstalledPackages|getInstalledApplications|PackageManager)/i, msg: '疑似获取已安装应用列表' },
        { re: /(android\.net\.wifi|WifiInfo|getDeviceId|getImei|TelephonyManager|getLine1Number)/i, msg: '疑似读取设备识别信息(IMEI/手机号)' },
        { re: /(android\.location|LocationManager|getLastKnownLocation)/i, msg: '疑似读取地理位置' },
        { re: /(Runtime\.getRuntime|ProcessBuilder)\s*\(\s*\)\s*\.exec/i, msg: '疑似执行系统命令' },
        { re: /(DexClassLoader|PathClassLoader|loadDex|System\.loadLibrary)/i, msg: '疑似动态加载外部代码' },
        { re: /(clipboard|ClipboardManager|getPrimaryClip)/i, msg: '疑似读取剪贴板' },
        { re: /(subprocess|os\.system|os\.popen|shutil\.rmtree)/, msg: '疑似执行系统命令/删除文件' },
        { re: /(smtplib|smtphost|sendmail)/i, msg: '疑似发送邮件外传数据' },
        { re: /(socks?\.socket|socket\.socket\s*\(\s*socket\.AF_INET\s*,\s*socket\.SOCK_RAW)/i, msg: '疑似原始套接字嗅探' }
    ];
    for (var i = 0; i < patterns.length; i++) {
        try { if (patterns[i].re.test(c)) risks.push(patterns[i].msg); } catch(e) {}
    }
    var uploadRe = /(requests?|session|httpx|urllib\.request|aiohttp)\.(post|put|upload|open)\s*\(/gi;
    var uploadCount = 0;
    try { var m; while ((m = uploadRe.exec(c)) !== null) uploadCount++; } catch(e) {}
    var hostCount = 0;
    try { var hostRe = /https?:\/\/(?!127\.0\.0\.1|localhost)([a-zA-Z0-9.-]+)/g; var hm; while ((hm = hostRe.exec(c)) !== null) hostCount++; } catch(e) {}
    if (uploadCount > 0 && hostCount > 3) risks.push('向 ' + hostCount + ' 个外部域名发送数据，请人工核对');
    return risks;
}

