function SourceStateManager(sourceId) {
    this.sourceId = sourceId || '';
}
SourceStateManager.prototype._read = function() {
    if (!this.sourceId) return {};
    try {
        var cr = $.require("customRule");
        if (cr.getSourceState) return cr.getSourceState(this.sourceId) || {};
    } catch(e) {}
    return {};
};
SourceStateManager.prototype._write = function(state) {
    if (!this.sourceId) return state || {};
    try {
        var cr = $.require("customRule");
        if (cr.setSourceState) return cr.setSourceState(this.sourceId, state || {});
    } catch(e) {}
    return state || {};
};
SourceStateManager.prototype.get = function(key, defValue) {
    var st = this._read();
    return st[key] !== undefined ? st[key] : defValue;
};
SourceStateManager.prototype.set = function(key, value) {
    var st = this._read();
    st[key] = value;
    st.updatedAt = Date.now();
    this._write(st);
};
SourceStateManager.prototype.merge = function(patch) {
    var st = this._read();
    patch = patch || {};
    for (var k in patch) {
        if (patch.hasOwnProperty(k)) st[k] = patch[k];
    }
    st.updatedAt = Date.now();
    this._write(st);
    return st;
};
SourceStateManager.prototype.clear = function(key) {
    var st = this._read();
    if (key) delete st[key];
    else st = {};
    this._write(st);
};

