    function getRank() {
        var chnNumChar = {零:0,一:1,二:2,三:3,四:4,五:5,六:6,七:7,八:8,九:9};
        var chnNameValue = {
            十:{value:10,secUnit:false}, 百:{value:100,secUnit:false},
            千:{value:1000,secUnit:false}, 万:{value:10000,secUnit:true},
            亿:{value:100000000,secUnit:true}
        };
        function ChineseToNumber(chnStr) {
            var rtn = 0, section = 0, number = 0, secUnit = false;
            var str = chnStr.split('');
            for (var i = 0; i < str.length; i++) {
                var num = chnNumChar[str[i]];
                if (typeof num !== 'undefined') {
                    number = num;
                    if (i === str.length - 1) section += number;
                } else {
                    var unit = chnNameValue[str[i]].value;
                    secUnit = chnNameValue[str[i]].secUnit;
                    if (secUnit) { section = (section + number) * unit; rtn += section; section = 0; }
                    else { section += (number * unit); }
                    number = 0;
                }
            }
            return rtn + section;
        }
        function nameCompare(a, b) {
            if (a == null || b == null) return a == null ? b == null ? 0 : -1 : 1;
            a = a.replace(/([零一二三四五六七八九十百千万亿])/g, function(m) { return ChineseToNumber(m); });
            b = b.replace(/([零一二三四五六七八九十百千万亿])/g, function(m) { return ChineseToNumber(m); });
            var NUMBERS = java.util.regex.Pattern.compile("(?<=\\D)(?=\\d)|(?<=\\d)(?=\\D)");
            var split1 = NUMBERS.split(new java.lang.String(a));
            var split2 = NUMBERS.split(new java.lang.String(b));
            for (var i = 0; i < Math.min(split1.length, split2.length); i++) {
                var c1 = split1[i].charCodeAt(0);
                var c2 = split2[i].charCodeAt(0);
                var cmp = 0;
                var zero = '0'.charCodeAt(0), nine = '9'.charCodeAt(0);
                if (c1 >= zero && c1 <= nine && c2 >= zero && c2 <= nine) {
                    cmp = new java.math.BigInteger(split1[i]).compareTo(new java.math.BigInteger(split2[i]));
                }
                if (cmp === 0) {
                    var regex = /[a-zA-Z0-9]/;
                    var s1 = String(split1[i]), s2 = String(split2[i]);
                    if (regex.test(s1) || regex.test(s2)) {
                        cmp = new java.lang.String(split1[i]).compareTo(new java.lang.String(split2[i]));
                    } else {
                        cmp = s1.localeCompare(s2, 'zh');
                    }
                }
                if (cmp !== 0) return cmp;
            }
            return split1.length - split2.length;
        }
        function rank(list, m, o) {
            if (m === "名称") {
                list = Array.from(list).sort(function(a, b) { return nameCompare(String(a.getName()).toUpperCase(), String(b.getName()).toUpperCase()); });
            } else if (m === "大小") {
                list = Array.from(list).sort(function(a, b) { return a.length() - b.length(); });
            } else if (m === "时间") {
                list = Array.from(list).sort(function(a, b) { return a.lastModified() - b.lastModified(); });
            }
            if (o === "I") return list.reverse();
            return list;
        }
        return rank;
    }

