        function choose(configs, isBack, id, menuType) {
            function click(configs, isBack, id) {
                var callbackFunc = new Function("PATH", "TYPE", "ID", "return " + configs.callback);
                var v = findItem(id).extra;
                var path = v.path, type = v.type;
                $.hiker.input = path;
                var callbackResult = callbackFunc(path, type, id);
                if (callbackResult === true) {
                    if (isBack) {
                        putMyVar(configs.uid + ":back", "true");
                        updateItem({ extra: findItem(configs.uid + "#搜索框1").extra });
                    }
                    back(false);
                    return "hiker://empty";
                } else if (callbackResult === false) {
                    return "hiker://empty";
                }
                return callbackResult;
            }
            function menu(click, configs, isBack, id, input) {
                if (input === "打开") return click(configs, isBack, id);
                var v = findItem(id).extra;
                var path = v.path;
                var fileUtil = com.example.hikerview.utils.FileUtil;
                switch (input) {
                    case "复制路径": return "copy://" + path;
                    case "编辑文件": return "editFile://file://" + path;
                    case "删除文件": deleteFile("file://" + path); deleteItem(id); return "toast://已删除";
                    case "分享文件": return "share://" + path;
                    case "外部打开": return "openFile://file://" + path;
                    case "文件详细":
                        try {
                            var file = new File(path);
                            return $("文件名称：" + fileUtil.getFileName(path) + "\n文件大小：" + fileUtil.getFormatedFileSize(fileUtil.getFolderSize(file)) + "\n最后修改时间：" + $.dateFormat(file.lastModified(), "yyyy/MM/dd/hh:mm:ss")).confirm(function() {});
                        } catch (e) { return "toast://权限不足或获取失败"; }
                    case "重命名":
                        var oldName = fileUtil.getFileName(path);
                        return $(oldName, "输入新的名字").input(function(path, id, oldName, configs) {
                            if (input.trim() === "" || oldName === input) return "toast://请输入新名字";
                            var code = $.require("function").fileSelect;
                            try {
                                var topath;
                                if (!(topath = code.getFileUtil().renameFile(path, input))) return "toast://重命名失败";
                                var extra = findItem(id).extra;
                                extra.type = "." + com.example.hikerview.utils.FileUtil.getFileSuffix(input);
                                extra.path = topath;
                                updateItem({ title: input, pic_url: code.getIconPath().getIconPath(extra.path, extra.type), extra: extra });
                                return "toast://改名完成";
                            } catch (e) { return "toast://" + e.toString(); }
                        }, path, id, oldName, configs);
                }
            }
            if (menuType) return menu(click, configs, isBack, id, menuType);
            return click(configs, isBack, id);
        }

        function findFile(baseDir, findFunc, callback, depth) {
            depth = depth || 0;
            if (!baseDir.exists() || !baseDir.isDirectory() || depth > 5) return;
            var files = baseDir.listFiles();
            if (files == null) return;
            for (var i = 0; i < files.length; i++) {
                var file = files[i];
                var isDirectory = file.isDirectory();
                if (findFunc(String(file.getName()))) callback(file, isDirectory);
                if (isDirectory) findFile(file, findFunc, callback, depth + 1);
            }
        }

        function labels(path, configs, count) {
            var load = $.require("function").fileSelect.init().loadFile;
            var lastCount = findItem(configs.uid + "#变量").extra.count || count;
            var del = [];
            for (var i = count + 1; i <= lastCount; i++) del.push(configs.uid + "#路径" + i);
            if (del.length > 0) deleteItem(del);
            java.lang.Thread.sleep(50);
            load(path, configs, true);
            return "hiker://empty";
        }

        function loadTag(pathT, configs) {
            var targetPath, datumPath;
            if (configs === undefined) {
                configs = pathT;
                targetPath = configs.initialPath;
                datumPath = configs.rootDirPath;
            } else {
                targetPath = pathT;
                datumPath = findItem(configs.uid + "#变量").extra.currentPath;
            }
            targetPath = Paths.get(targetPath);
            datumPath = Paths.get(datumPath);
            var targetCount = targetPath.getNameCount();
            var datumCount = datumPath.getNameCount();
            var tempPath = datumPath;
            if (targetCount >= datumCount) {
                for (var i = datumCount; i > 0 && i < targetCount; i++) {
                    tempPath = tempPath.resolve(targetPath.getName(i));
                    addItemAfter(configs.uid + "#路径" + (i - 1), {
                        title: tempPath.getFileName() + " >",
                        col_type: "scroll_button",
                        url: $("#noLoading#").lazyRule(labels, tempPath.toString(), configs, i),
                        extra: { id: configs.uid + "#路径" + i }
                    });
                }
            } else {
                var del = [];
                for (var i = targetCount; i > 0 && i < datumCount; i++) del.push(configs.uid + "#路径" + i);
                deleteItem(del);
            }
            return targetPath;
        }

        exports.loadFile = function(path, configs, noTag) {
            var dirPath;
