                        url: configs.multiple ? $("#noLoading#").lazyRule(toggleSel, fpath, configs, id, name) : $(tips.replace("${name}", name).replace("${path}", fpath))[configs.onClickType](choose, configs, false, id),
                        pic_url: pic_url,
                        col_type: colType,
                        extra: {
                            cls: configs.uid + ".文件(夹) " + itemCls,
                            id: id, path: fpath, type: type,
