                                { title: "编辑文件", js: $.toString(choose, configs, false, id, "编辑文件") },
                                { title: "重命名", js: $.toString(choose, configs, false, id, "重命名") },
                                { title: "分享文件", js: $.toString(choose, configs, false, id, "分享文件") },
                                { title: "文件详细", js: $.toString(choose, configs, false, id, "文件详细") },
                                { title: "外部打开", js: $.toString(choose, configs, false, id, "外部打开") },
                                { title: "删除文件", js: $.toString(choose, configs, false, id, "删除文件") }
                            ]
                        }
                    });
                }
            });
            var fa = wjj.length > 0, fb = wj.length > 0;
            java.lang.Thread.sleep(40);
            if (fa) addItemAfter(configs.uid + "#文件夹", wjj);
            if (fb) addItemAfter(configs.uid + "#文件", wj);
            java.lang.Thread.sleep(65);
            if (wjj.length > 10 || wj.length > 10 || wjj.length + wj.length > 10) {
                updateItem(configs.uid + "#Bottom", { title: "““””<small><font color='gray'>到底了哦</font></small>", col_type: "text_center_1" });
            } else if (!(fa || fb)) {
