        exports.loadSearch = function(key, configs) {
            deleteItemByCls(configs.uid + ".搜索-文件夹");
            deleteItemByCls(configs.uid + ".搜索-文件");
            if (key == "") return;
            var path = findItem(configs.uid + "#变量").extra.currentPath;
            var targetType = new RegExp("(" + configs.fileType + ")$");
            var wjj = [], wj = [];
            var tips = configs.onClickType === "confirm" ? configs.cSearchTips : "#noLoading#";
            var itemId = $this.getId(7);
            var iki = 0;
            var colType = findItem(configs.uid + "#样式").extra.colType;
            var findFunc;
            if (configs.isRegular) {
                var keyReg = new RegExp(key);
                findFunc = function(name) { return keyReg.test(name); };
            } else {
                findFunc = function(name) { return name.indexOf(key) !== -1; };
            }
            findFile(new File(path), findFunc, function(file, isDirectory) {
                var name = String(file.getName());
                var fpath = String(file.getPath());
                if (isDirectory) {
                    wjj.push({
                        title: name,
                        url: $("#noLoading#").lazyRule(refreshDir, fpath, configs, true),
                        pic_url: dirIcon,
