                    }, configs, input, isRegular);
                }
            }, configs),
            desc: "请输入文件名或文件路径",
            col_type: "input",
            extra: { id: configs.uid + "#搜索框1", onChange: $.toString(function(uid) {
                if (getMyVar(uid + ":back", "") === "true") {
