                    if (files == null) return "toast://权限不足或获取失败";
                    var targetType = configs.fileType ? new RegExp("(" + configs.fileType + ")$") : null;
                    var key = configs.uid + ":sel";
                    var cur = String(getMyVar(key, "")).split("\n").filter(function(x) { return x; });
                    var curSet = {}, localSet = {};
                    for (var ci = 0; ci < cur.length; ci++) curSet[cur[ci]] = true;
                    for (var fi = 0; fi < files.length; fi++) {
                        var f = files[fi];
                        if (f.isDirectory()) continue;
