var cacheManager = {
    danmuDir: 'hiker://files/rules/星集Media/',
    cacheDir: 'hiker://files/cache/',
    tmpDir: 'hiker://files/_cache/',
    _patternToRegex: function(pattern) {
        var escaped = String(pattern).replace(/[.+^${}()|[\]\\]/g, '\\$&');
        escaped = escaped.replace(/\*/g, '.*').replace(/\?/g, '.');
        return new RegExp('^' + escaped + '$');
    },
    _resolveDir: function(hikerDir) {
        try {
            var p = String(getPath(hikerDir) || '');
            if (p.indexOf('file://') === 0) p = p.slice(7);
            return p;
        } catch (e) { return ''; }
    },
    _cleanDir: function(hikerDir, pattern, maxAgeMs, now) {
        var count = 0, bytes = 0;
        try {
            var dir = new java.io.File(this._resolveDir(hikerDir));
            if (!dir.exists() || !dir.isDirectory()) return 0;
            var files = dir.listFiles();
            if (!files) return 0;
            var regex = this._patternToRegex(pattern);
            for (var i = 0; i < files.length; i++) {
                var f = files[i];
                if (f.isDirectory()) continue;
                if (!regex.test(String(f.getName()))) continue;
                try {
                    var lastMod = f.lastModified();
                    if ((now - lastMod) >= maxAgeMs) { bytes += f.length(); if (f.delete()) count++; }
                } catch (e) {}
            }
        } catch (e) {}
        return { count: count, bytes: bytes };
    },
    _countDir: function(hikerDir, pattern, target) {
        try {
            var dir = new java.io.File(this._resolveDir(hikerDir));
            if (!dir.exists() || !dir.isDirectory()) return;
            var files = dir.listFiles();
            if (!files) return;
            var regex = this._patternToRegex(pattern);
            for (var i = 0; i < files.length; i++) {
                var f = files[i];
                if (f.isDirectory()) continue;
                if (!regex.test(String(f.getName()))) continue;
                target.count++;
                try { target.size += f.length(); } catch (e) {}
            }
        } catch (e) {}
    },
    autoCleanIfExpired: function() {
        try {
            var lastClean = parseInt(getMyVar('xj_last_auto_clean', '0')) || 0;
            var now = Date.now();
            if (now - lastClean < 24 * 60 * 60 * 1000) return null;
            putMyVar('xj_last_auto_clean', String(now));
            var days = parseInt(getItem('xj_cache_max_days', '7'));
            if (isNaN(days) || days <= 0) return null;
            return this.cleanExpired(days);
        } catch (e) { return null; }
    },
    cleanExpired: function(maxAgeDays) {
        var result = { danmu: 0, layer: 0, tmp: 0, bytes: 0 };
        try {
            if (maxAgeDays === undefined || maxAgeDays === null) maxAgeDays = 7;
            maxAgeDays = parseInt(maxAgeDays);
            if (isNaN(maxAgeDays) || maxAgeDays < 0) maxAgeDays = 7;
            var maxAgeMs = maxAgeDays * 24 * 60 * 60 * 1000;
            var now = Date.now();
            var r1 = this._cleanDir(this.danmuDir, 'external_danmu_*.json', maxAgeMs, now);
            var r2 = this._cleanDir(this.cacheDir, 'xj_*.json', maxAgeMs, now);
            var r3 = this._cleanDir(this.tmpDir, 'xj_*', maxAgeMs, now);
            result.danmu = r1.count; result.layer = r2.count; result.tmp = r3.count;
            result.bytes = r1.bytes + r2.bytes + r3.bytes;
        } catch (e) {}
        return result;
    },
    cleanAll: function() {
        return this.cleanExpired(0);
    },
    getStats: function() {
        var stats = {
            danmu: { count: 0, size: 0 },
            layer: { count: 0, size: 0 },
            tmp: { count: 0, size: 0 },
            total: { count: 0, size: 0 }
        };
        try {
            this._countDir(this.danmuDir, 'external_danmu_*.json', stats.danmu);
            this._countDir(this.cacheDir, 'xj_*.json', stats.layer);
            this._countDir(this.tmpDir, 'xj_*', stats.tmp);
            stats.total.count = stats.danmu.count + stats.layer.count + stats.tmp.count;
            stats.total.size = stats.danmu.size + stats.layer.size + stats.tmp.size;
        } catch (e) {}
        return stats;
    },
    formatSize: function(bytes) {
        bytes = Number(bytes) || 0;
        if (bytes < 1024) return bytes + 'B';
        if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + 'KB';
        if (bytes < 1024 * 1024 * 1024) return (bytes / (1024 * 1024)).toFixed(1) + 'MB';
        return (bytes / (1024 * 1024 * 1024)).toFixed(2) + 'GB';
    }
};

function xjTvboxJoinPath(base, rel) {
    if (!rel || typeof rel !== 'string') return rel;
    if (rel.indexOf('http') === 0 || rel.indexOf('file://') === 0 || rel.indexOf('/') === 0) return rel;
    if (rel.indexOf('./') !== 0 && rel.indexOf('../') !== 0) return rel;
    if (base.indexOf('file://') === 0) {
        var baseDir = base.substring(7, base.lastIndexOf('/'));
        var parts = baseDir.split('/');
        var relParts = rel.split('/');
        for (var i = 0; i < relParts.length; i++) {
            if (relParts[i] === '.') continue;
            else if (relParts[i] === '..') parts.pop();
            else parts.push(relParts[i]);
        }
        return 'file://' + parts.join('/');
    } else if (base.indexOf('http') === 0) {
        return joinUrl(base, rel);
    }
    return rel;
}

function xjFetchTvboxContent(path) {
    if (!path) return '';
    if (path.indexOf('http') === 0) {
        return fetch(path, { headers: { "User-Agent": "okhttp/4.12.0" }, timeout: 20000 }) || '';
    }
    if (path.indexOf('file://') === 0) {
        return readFile(path.substring(7)) || '';
    }
    return readFile(path) || '';
}

function xjParseTvboxConfig(content) {
    if (!content) return null;
    content = content.replace(/\/\*[\s\S]*?\*\//g, '').trim();
    var cfgObj;
    try {
        cfgObj = JSON.parse(content);
    } catch (e) {
        try {
            var module = { exports: {} };
            var exports = module.exports;
            eval(content);
            cfgObj = module.exports || {};
            if (typeof cfgObj === 'string') cfgObj = JSON.parse(cfgObj);
        } catch (e2) {
            return null;
        }
    }
    return cfgObj;
}

function xjResolveTvboxExt(configPath, ext) {
    var sExt = '';
    if (typeof ext === 'object') {
        sExt = JSON.stringify(ext);
    } else if (typeof ext === 'string') {
        if (ext.indexOf('./') === 0 || ext.indexOf('../') === 0) {
            var absExtPath = xjTvboxJoinPath(configPath, ext);
            if (/\.json(\?|$)/i.test(absExtPath)) {
                try { sExt = xjFetchTvboxContent(absExtPath) || absExtPath; } catch (e) { sExt = absExtPath; }
            } else {
                sExt = absExtPath;
            }
        } else {
            sExt = ext;
        }
    }
    return sExt;
}

function xjImportTvboxSites(configPath, configName, cfgObj, opts) {
    opts = opts || {};
    var clearOld = opts.clearOld !== false;
    var c = getXjBase();
