    }
    c.tvbox_site_keys = siteKeys;
    if (configName) c.tvbox_config_name = configName;
    if (absSpider) {
        if (!c.jar_settings) c.jar_settings = { spider: '' };
        c.jar_settings.spider = absSpider;
    }
    saveXjBase(c);
    var tvboxRecPath = "hiker://files/rules/星集Media/xj_tvbox.json";
