    if (!size) return "0";
    var units = ["B", "KB", "MB", "GB", "TB"];
    var i = 0;
    while (size >= 1024) { size /= 1024; i++; }
    return (i ? Number(size.toFixed(2)) : size) + " " + units[i];
}

