}

function sortSx(arr, name, style, order) {
    if (style == 1) {
        arr.sort((a, b) => {
            var va = String(a[name] || "");
            var vb = String(b[name] || "");
            return va.localeCompare(vb);
        });
    } else if (style == 2) {
        arr.sort((a, b) => {
            var va = String(a[name] || "");
            var vb = String(b[name] || "");
            return va.localeCompare(vb);
        });
        var m = arr.findIndex(it => /^[\u4e00-\u9fa5]/.test(String(it[name] || "")));
        var n = arr.findLastIndex(it => /^[\u4e00-\u9fa5]/.test(String(it[name] || "")));
        if (m > -1) { var tmp = arr.splice(m, n - m + 1); arr = arr.concat(tmp); }
    } else if (style == 3) {
        arr.sort((a, b) => {
            var na = parseInt((String(a[name] || "").match(/\d+/) || [99999999999999])[0]);
            var nb = parseInt((String(b[name] || "").match(/\d+/) || [99999999999999])[0]);
            return na - nb;
        });
    }
    if (order == 1) arr.reverse();
    var dirs = arr.filter(it => it.isdir == 1);
    var files = arr.filter(it => it.isdir != 1);
    return dirs.concat(files);
}

function matchBaiduLink(input) {
    if (typeof input !== "string") input = String(input || "");
    if (input.includes("baidu")) {
        var path1;
        if (input.includes("pwd=")) {
            if (input.includes("/s/")) {
                path1 = input.match(/([\w_-]{23}).+pwd=(\w+)/);
                if (path1) return path1[1] + "?pwd=" + path1[2];
            } else if (input.includes("surl=")) {
                path1 = input.match(/([\w_-]{22}).+pwd=(\w+)/);
                if (path1) return "1" + path1[1] + "?pwd=" + path1[2];
            }
        } else if (input.includes("提取码")) {
            path1 = input.match(/([\w_-]{23})提取码:(\w+)/);
            if (path1) return path1[1] + "?pwd=" + path1[2];
        }
    }
    return input;
}

