function parseShareUrl(url) {
    if (!url || typeof url !== 'string') return { shareKey: '', sharePwd: '' };
    var shareKey = '';
    var sharePwd = '';
    var patterns = [
        /\/\/[^\/]*123(?:pan|865)?\.(?:com|cn)\/s\/([a-zA-Z0-9_-]+)(?:\.html)?/i,
        /\/\/[^\/]*123(?:pan|865)?\.(?:com|cn)\/123pan\/([a-zA-Z0-9_-]+)/i,
        /\/\/[^\/]*123(?:pan|865)?\.(?:com|cn)\/share\/(?:view\/)?([a-zA-Z0-9_-]+)/i,
        /[?&](?:sharekey|key)=([a-zA-Z0-9_-]+)/i,
        /123(?:pan|865)?\.(?:com|cn)\/s\/([a-zA-Z0-9_-]+)/i
    ];
    for (var i = 0; i < patterns.length; i++) {
        var match = url.match(patterns[i]);
        if (match) { shareKey = match[1]; break; }
    }
    if (shareKey && shareKey.indexOf('.') !== -1) {
        shareKey = shareKey.substring(0, shareKey.indexOf('.'));
    }
    var pwdPatterns = [
        /[?&](?:密码|code|pwd|key)=([a-zA-Z0-9]{4})/i,
        /密码[^\w]*([a-zA-Z0-9]{4})/,
        /提取码[^\w]*([a-zA-Z0-9]{4})/,
        /访问码[^\w]*([a-zA-Z0-9]{4})/
    ];
    for (var j = 0; j < pwdPatterns.length; j++) {
        var m = url.match(pwdPatterns[j]);
        if (m) { sharePwd = m[1]; break; }
    }
    return { shareKey: shareKey, sharePwd: sharePwd };
}

function decrypt(encryptedStr) {
    try {
        var trimmedStr = encryptedStr.trim();
        var standardBase64 = trimmedStr.replace(/-/g, '+').replace(/_/g, '/');
        var remainder = standardBase64.length % 4;
        if (remainder > 0) standardBase64 += '='.repeat(4 - remainder);
        var Base64 = android.util.Base64;
        var Cipher = javax.crypto.Cipher;
        var IvParameterSpec = javax.crypto.spec.IvParameterSpec;
        var SecretKeySpec = javax.crypto.spec.SecretKeySpec;
        var secretKey = 'pXce-DF4m7FnlftioS2nwg==';
        var keyBytes = new java.lang.String(secretKey).getBytes('UTF-8');
        var decode = Base64.decode(standardBase64, 0);
        if (decode.length < 16) return '';
        var ivBytes = java.util.Arrays.copyOfRange(decode, 0, 16);
        var cipherText = java.util.Arrays.copyOfRange(decode, 16, decode.length);
        var secretKeySpec = new SecretKeySpec(keyBytes, 'AES');
        var ivSpec = new IvParameterSpec(ivBytes);
        var cipher = Cipher.getInstance('AES/CBC/PKCS5Padding');
        cipher.init(Cipher.DECRYPT_MODE, secretKeySpec, ivSpec);
        var decryptedBytes = cipher.doFinal(cipherText);
        return new java.lang.String(decryptedBytes, 'UTF-8');
    } catch(e) {
        return '';
    }
}

function parseReferer(url) {
    try {
        var query = new java.net.URI(url).getQuery();
        if (!query) return '';
        var params = query.split('&');
        for (var i = 0; i < params.length; i++) {
            var kv = params[i].split('=', 2);
            if (kv[0] === 'ref') return decrypt(kv[1]);
        }
        return '';
    } catch(e) { return ''; }
}

function getDirectUrl(rawUrl) {
