}

function buildUrl(base, params) {
    var url = base;
    if (params) {
        var parts = [];
        for (var key in params) {
            if (params.hasOwnProperty(key)) {
                parts.push(encodeURIComponent(key) + '=' + encodeURIComponent(params[key]));
            }
        }
        if (parts.length > 0) url += (url.indexOf('?') === -1 ? '?' : '&') + parts.join('&');
    }
    return url;
}

