    for (let it of list) {
        if (id == it.getBaseExtra().getId()) {
            ii = i;
            break;
        }
        i++;
    }
    if (ii < 0) return null;
    let mg = recyclerView.getLayoutManager();
    return mg.getChildAt(ii);
}

