        var matches = play_list.match(regex);
        if (matches) {
            matches.forEach(function(match) {
                var name = match.match(/RESOLUTION=(\d+x\d+)/)[1];
                var url1 = match.match(/[\r\n]+(.*?index\.m3u8\?.*?)(?=[\r\n]|$)/)[1];
