function extractEpKey(name) {
    var s = (name || '').replace(/\s+/g, '');
    var dm = s.match(/(\d{8})/);
    if (dm) return dm[1];
    dm = s.match(/(\d{6})/);
    if (dm) return dm[1];
    var cnMap = {'零':0,'一':1,'二':2,'三':3,'四':4,'五':5,'六':6,'七':7,'八':8,'九':9,'十':10,'百':100,'千':1000};
    var cm = s.match(/第([零一二三四五六七八九十百千]+)[集期话話季]/);
    if (cm) {
        var r = 0, cur = 0;
        for (var i = 0; i < cm[1].length; i++) {
            var v = cnMap[cm[1][i]];
            if (v >= 10) { cur = cur === 0 ? v : cur * v; r += cur; cur = 0; }
            else cur = v;
        }
        r += cur;
        if (r > 0) return String(r);
    }
    var em = s.match(/(?:第|ep|EP|e|E)\s*(\d+)/);
    if (em) return em[1];
    var nm = s.match(/(\d+)/);
    if (nm) return nm[1];
    return s;
}

