function doAutoMatch(obj, results) {
    if (!selectedSeasonData || !selectedSeasonData.episodes) return;
    results = (results || []).filter(function(r) { return r && (r.type === 'bocai' || r.type === 'merged_bocai'); });
    if (results.length === 0) return;
    var seasonEps = selectedSeasonData.episodes;
    var selSeason = selectedSeries ? selectedSeries.season : 1;
    var matchCacheKey = 'tmdb_match_' + tmdbId + '_s' + selSeason;
    var directMatches = {};
    var needAiEps = [];

    if (!forceRefresh) {
        try {
            var cm = tmdbCacheGet(matchCacheKey);
            if (cm && cm.directMatches) {
                directMatches = cm.directMatches;
                needAiEps = cm.needAiEps || [];
            }
        } catch(e) {}
    }

    if (Object.keys(directMatches).length === 0) {
        for (var di = 0; di < seasonEps.length; di++) {
            var dep = seasonEps[di];
            var depNum = dep.episode_number;
            var depName = dep.name || '';
            var depDate = dep.air_date || '';
            var depLocalTitle = depName;
            var depHasEpNum = depLocalTitle.match(/第\s*\d+\s*[期集]/) || depLocalTitle.match(/第\s*[一二三四五六七八九十百千]+\s*[期集]/);
            if (!depLocalTitle) {
                depLocalTitle = '第' + depNum + '集';
            } else if (!depHasEpNum) {
                depLocalTitle = '第' + depNum + '集 ' + depLocalTitle;
            }
            var depBindings = [];

            for (var dsi = 0; dsi < results.length; dsi++) {
                var dSrc = results[dsi];
                var dEps = dSrc.playUrl.split('#').filter(function(e) { return e; });
                for (var dei = 0; dei < dEps.length; dei++) {
                    var dEpName = (dEps[dei].split('$')[0] || '').trim();
                    var matched = false;

                    var epNumMatch = dEpName.match(/第(\d+)[集期]/);
                    if (epNumMatch && parseInt(epNumMatch[1]) === depNum) matched = true;
                    if (!matched && /^\d+$/.test(dEpName) && parseInt(dEpName) === depNum) matched = true;
                    if (!matched && depDate && dEpName.indexOf(depDate) >= 0) matched = true;
                    if (!matched) {
                        var localFeature = depLocalTitle.replace(/第\s*\d+\s*[期集]\s*/, '').trim();
                        if (localFeature && localFeature.length >= 2 && dEpName.indexOf(localFeature) >= 0) matched = true;
                        var upDown = depName.match(/[上下中]/);
                        if (upDown && dEpName.indexOf(upDown[0]) >= 0) {
                            var dEpNum = dEpName.match(/(\d+)/);
                            if (dEpNum && parseInt(dEpNum[1]) === depNum) matched = true;
                        }
                    }
                    if (!matched && depName && depName.length >= 2 && dEpName.indexOf(depName) >= 0) matched = true;

                    if (matched) depBindings.push({ s: dsi, e: dei });
                }
            }
            if (depBindings.length > 0) {
                directMatches[depNum] = depBindings;
            }
        }

        for (var ai2 = 0; ai2 < seasonEps.length; ai2++) {
            var aep2 = seasonEps[ai2];
            if (!directMatches[aep2.episode_number] && sparkKey && aep2.overview && aep2.overview.length < 24) {
                needAiEps.push(aep2);
            }
        }

        try { tmdbCachePut(matchCacheKey, { directMatches: directMatches, needAiEps: needAiEps }); } catch(e) {}
    }

    var epMatchStore = {};
    for (var ai = 0; ai < seasonEps.length; ai++) {
        var aep = seasonEps[ai];
        var aepNum = aep.episode_number;
        if (directMatches[aepNum]) {
            var dBindings = directMatches[aepNum];
            var dUrls = [];
            var dNames = [];
            var dRIds = [];
            var dFlags = [];
            for (var dbi = 0; dbi < dBindings.length; dbi++) {
                var db = dBindings[dbi];
                if (db.s >= 0 && db.s < results.length) {
                    var dSrcR = results[db.s];
                    var dSrcEps = dSrcR.playUrl.split('#').filter(function(e) { return e; });
                    if (db.e >= 0 && db.e < dSrcEps.length) {
                        var dParts = dSrcEps[db.e].split('$');
                        var dLink = dParts[1] || dParts[0] || '';
                        if (dLink) {
                            dUrls.push(dLink);
                            dNames.push(dSrcR.name || ('源' + db.s));
                            dRIds.push(dSrcR._ruleId || '');
                            dFlags.push(dSrcR.playFrom || dSrcR.name || '');
                        }
                    }
                }
            }
            if (dUrls.length > 0) {
                var dEpName = aep.name || '';
                var dHasEpNum = dEpName.match(/第\s*\d+\s*[期集]/) || dEpName.match(/第\s*[一二三四五六七八九十百千]+\s*[期集]/);
                if (!dEpName) dEpName = '第' + aepNum + '集';
                else if (!dHasEpNum) dEpName = '第' + aepNum + '集 ' + dEpName;
                epMatchStore[aepNum] = { epName: dEpName, urls: dUrls, names: dNames, rIds: dRIds, flags: dFlags };
                var dFrozenUrls = dUrls.slice();
                var dFrozenNames = dNames.slice();
                var dFrozenRIds = dRIds.slice();
                var dFrozenFlags = dFlags.slice();
                (function(epN, epNm, fU, fN, fR, fFl, oI) {
                    try {
                        updateItem('tmdb_ep_' + epN, {
                            title: '\uD83C\uDFAF ' + epNm,
                            url: $(fU.join('||')).lazyRule(function(dId, eTitle, eUrls, sNames2, rIds, eFlags, pLink, mTitle) {
                                var fn = $.require('function');
                                var vUrls = [];
                                var vHeaders = [];
                                for (var si = 0; si < eUrls.length; si++) {
                                    var resolvedUrl = eUrls[si];
                                    var lazyHdr = null;
                                    if (rIds[si]) {
                                        try {
                                            var cr = $.require('customRule');
                                            var rules = cr.getRuleList ? cr.getRuleList() : cr.getRuleIndex();
                                            var ruleObj = null;
                                            for (var ri = 0; ri < rules.length; ri++) {
                                                if (rules[ri].id === rIds[si]) { ruleObj = rules[ri]; break; }
                                            }
                                            if (ruleObj) {
                                                var eFlag = eFlags[si] || sNames2[si] || '';
                                                if (eFlag === '克隆' || eFlag === '去广告') eFlag = sNames2[0] || eFlag;
                                                var parsed = cr.executeLazy(ruleObj, resolvedUrl, eFlag);
                                                if (parsed) {
                                                    if (parsed && typeof parsed === 'object' && Array.isArray(parsed.urls)) {
                                                        if (parsed.headers && parsed.headers[0]) lazyHdr = parsed.headers[0];
                                                        resolvedUrl = String(parsed.urls[0] || '');
                                                    } else {
                                                        resolvedUrl = parsed;
                                                    }
                                                }
                                            }
                                        } catch (eLz) {}
                                    }
                                    if (typeof resolvedUrl === 'string' && resolvedUrl.indexOf('pan://') === 0) {
                                        return fn.resolvePanJump(resolvedUrl);
                                    }
                                    if (typeof resolvedUrl === 'string' && resolvedUrl.indexOf('{"urls"') === 0) {
                                        try {
                                            var pj = JSON.parse(resolvedUrl);
                                            if (pj.urls && pj.urls.length > 0) {
                                                if (pj.headers && pj.headers[0]) lazyHdr = pj.headers[0];
                                                resolvedUrl = String(pj.urls[0]);
                                            }
                                        } catch (ePj) {}
                                    }
                                    if (/^video:\/\//i.test(resolvedUrl) || /#isVideo=true#/.test(resolvedUrl)) {
                                        vUrls.push(resolvedUrl);
                                    } else if (/\.m3u8|\.mp4|\.flv/i.test(resolvedUrl)) {
                                        vUrls.push(resolvedUrl + '#isVideo=true#');
                                    } else if (/^https?:\/\//i.test(resolvedUrl)) {
                                        vUrls.push('video://' + resolvedUrl + '#isVideo=true#');
                                    } else if (/^(hiker:|pics:|audio:|web:|x5Rule:|webRule:|magnet:|thunder:|push:)/i.test(resolvedUrl)) {
                                        vUrls.push(resolvedUrl);
                                    } else {
                                        continue;
                                    }
                                    vHeaders.push(lazyHdr || {});
                                }
                                if (vUrls.length === 0) return 'toast://链接解析失败,该源解析无结果';
                                var result = { urls: vUrls, names: sNames2 };
                                var hasHdr = false;
                                for (var hi = 0; hi < vHeaders.length; hi++) { if (vHeaders[hi] && vHeaders[hi]['User-Agent']) { hasHdr = true; break; } }
                                if (hasHdr) result.headers = vHeaders;
                                var dmMode = fn.getExternalDanmuConfig().mode;
                                if (/\[画\]/.test(sNames2.join('')) || /\[音\]/.test(sNames2.join(''))) dmMode = 'off';
                                if (dmMode === 'external' || dmMode === 'local') {
                                    var dm = fn.getExternalDanmuUrl(pLink, mTitle || '', '', eTitle);
                                    if (dm) result.danmu = dm;
                                }
                                return JSON.stringify(result);
                            }, oI, epNm, fU, fN, fR, fFl, fU.join('||'), obj.title || '')
                        });
                    } catch (e) {}
                })(aepNum, dEpName, dFrozenUrls, dFrozenNames, dFrozenRIds, dFrozenFlags, obj.id);
            }
        }
    }

    try { putMyVar('tmdb_ep_match_bc_' + obj.id, JSON.stringify(epMatchStore)); } catch(eMs) {}

    if (needAiEps.length > 0 && sparkKey && !getMyVar('tmdb_ai_running', '')) {
        putMyVar('tmdb_ai_running', '1');
        var aiMatchData = {
            seasonEpisodes: needAiEps.map(function(ep) {
                return { ep_number: ep.episode_number, name: ep.name || '', air_date: ep.air_date || '', overview: (ep.overview || '').substring(0, 100) };
            }),
            sources: results.map(function(r) {
                var eps = r.playUrl.split('#').filter(function(e) { return e; });
                return { name: r.name || r.playFrom || '', key: r.key, epCount: eps.length, playUrl: r.playUrl, _ruleId: r._ruleId || '', playFrom: r.playFrom || '' };
            }),
            selectedSeason: selSeason,
            sparkKey: sparkKey,
            objId: obj.id,
            movieTitle: obj.title || ''
        };
        be([{
            func: function(data) {
                try { doAIMatchAsync(data); } catch (e) { putMyVar('tmdb_ai_running', ''); }
            },
            param: aiMatchData
        }]);
    }
}

function doAIMatchAsync(data) {
    var seasonEps = data.seasonEpisodes;
    var sources = data.sources;
    var selSeason = data.selectedSeason;
    var sKey = data.sparkKey;
    var oId = data.objId;

    addItemBefore('bocai_agg', {
        title: '\u2018\u2018\u2019\u2019AI推理匹配中...',
        col_type: 'text_center_1',
