    });

    var prompt = '请将TMDB剧集与视频源选集进行匹配，为每一集都返回匹配结果。\n\n';
    prompt += '## TMDB剧集(第' + selSeason + '季,共' + seasonEps.length + '集)\n';
    for (var ti = 0; ti < seasonEps.length; ti++) {
        var te = seasonEps[ti];
        prompt += te.ep_number + ':' + te.name + '|' + te.air_date + '|' + (te.overview || '').substring(0, 30) + '\n';
    }
    prompt += '\n## 视频源\n';
    for (var si = 0; si < sources.length; si++) {
        var se = sources[si];
        var epNames = se.playUrl.split('#').filter(function(e) { return e; }).map(function(e) { return e.split('$')[0] || ''; });
        prompt += 'S' + si + ': ';
        for (var sj = 0; sj < epNames.length; sj++) prompt += sj + '.' + epNames[sj] + ' ';
        prompt += '\n';
