    prompt += '\n\n请为全部' + seasonEps.length + '集返回匹配:';

    try {
        var sparkModel = tmdbConfig.spark_model || 'xop3qwen1b7';
        var sparkResp = fetch('https://maas-api.cn-huabei-1.xf-yun.com/v2/chat/completions', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + sKey },
            body: JSON.stringify({
                model: sparkModel,
                messages: [
                    { role: 'system', content: '你是影视剧集匹配专家，只返回JSON格式的匹配结果，不要返回任何其他文字。' },
                    { role: 'user', content: prompt }
                ],
                temperature: 0.1,
                max_tokens: 8192
            }),
            timeout: 30000
        });

        var sparkData = JSON.parse(sparkResp || '{}');
        var aiContent = '';
        if (sparkData.choices && sparkData.choices[0] && sparkData.choices[0].message) {
            aiContent = sparkData.choices[0].message.content || '';
        }
        var aiMatches = {};
        var jsonMatch = aiContent.match(/\{[\s\S]*\}/);
        if (jsonMatch) {
            try {
                var matchObj = JSON.parse(jsonMatch[0]);
                if (matchObj.matches) {
                    for (var mi = 0; mi < matchObj.matches.length; mi++) {
                        var m = matchObj.matches[mi];
                        if (m.tmdb_ep && m.bindings) aiMatches[m.tmdb_ep] = m.bindings;
                    }
                }
            } catch (e) {}
        }

        deleteItem('ai_matching_tip');
        putMyVar('tmdb_ai_running', '');

        var aiStore = {};
        try { aiStore = JSON.parse(getMyVar('tmdb_ep_match_bc_' + oId, '') || '{}') || {}; } catch (eSt) { aiStore = {}; }

        for (var epi = 0; epi < seasonEps.length; epi++) {
            var ep = seasonEps[epi];
            var epNum = ep.ep_number;
            var bindings = aiMatches[epNum];

            if (bindings && bindings.length > 0) {
                var allUrls = [];
                var srcNames = [];
                var aiRIds = [];
                var aiFlags = [];
