                    if (srcIdx >= 0 && srcIdx < sources.length) {
                        var srcResult = sources[srcIdx];
                        var srcEps = srcResult.playUrl.split('#').filter(function(e) { return e; });
                        if (epIdx >= 0 && epIdx < srcEps.length) {
                            var srcParts = srcEps[epIdx].split('$');
