                if (allUrls.length > 0) {
                    var epName = ep.name || '';
                    var hasEpNum2 = epName.match(/第\s*\d+\s*[期集]/) || epName.match(/第\s*[一二三四五六七八九十百千]+\s*[期集]/) || epName.match(/^\d+$/);
                    if (!epName) epName = '第' + epNum + '集';
                    else if (!hasEpNum2) epName = '第' + epNum + '集 ' + epName;
                    var mergedPlayLink = allUrls.join('||');
                    var frozenUrls = allUrls.slice();
                    var frozenNames = srcNames.slice();
                    var frozenRIds = aiRIds.slice();
                    var frozenFlags = aiFlags.slice();
                    aiStore[epNum] = { epName: epName, urls: allUrls, names: srcNames, rIds: aiRIds, flags: aiFlags };
                    (function(epNum2, epName2, mergedLink, fUrls, fNames, fRIds, fFlags, oId2, mTitle2) {
                        try {
                            updateItem('tmdb_ep_' + epNum2, {
                                title: '\uD83C\uDFAF ' + epName2,
                                url: $(mergedLink).lazyRule(function(dId, eTitle, eUrls, sNames2, rIds, eFlags, pLink, mTitle) {
                                    var fn = $.require('function');
                                    var vUrls = [];
