                                            vUrls.push(resolvedUrl + '#isVideo=true#');
                                        } else if (/^https?:\/\//i.test(resolvedUrl)) {
                                            vUrls.push('video://' + resolvedUrl + '#isVideo=true#');
                                        } else if (/^(hiker:|pics:|audio:|web:|x5Rule:|webRule:|magnet:|thunder:|push:)/i.test(resolvedUrl)) {
                                            vUrls.push(resolvedUrl);
                                        } else {
