XJ._webParse = function(config, host, url) {
    try {
        if (!url) return '';
        if (/m3u8|mp4/i.test(url)) return url + '#isVideo=true#';
        if (!/^https?:\/\//.test(url)) url = host + (url.charAt(0) === '/' ? '' : '/') + url;
        var html = XJ.fetchHtml(url, config.ua || {});
        if (XJ.isManualVerifyMarker(html)) return url;
        if (!html) return 'video://' + url + '#isVideo=true#';
        var m = html.match(/r\s+player_\w+\s*=\s*(\{.*?\})\s*;?\s*<\/script>/);
        if (!m) {
            m = html.match(/(?:player_data|playerData)\s*=\s*(\{.*?\})\s*;?/);
        }
        if (!m) return 'video://' + url + '#isVideo=true#';
        var player;
        try { player = JSON.parse(m[1]); } catch (e) { return 'video://' + url + '#isVideo=true#'; }
        var jsurl = player.url || '';
        if (!jsurl) return 'video://' + url + '#isVideo=true#';
        if (player.encrypt === '1' || player.encrypt === 1) {
            try { jsurl = unescape(jsurl); } catch (e) {}
        } else if (player.encrypt === '2' || player.encrypt === 2) {
            try { jsurl = unescape(base64Decode(jsurl)); } catch (e) {}
        }
        if (/m3u8|mp4/i.test(jsurl)) return jsurl + '#isVideo=true#';
        return 'video://' + url + '#isVideo=true#';
    } catch (e) {
        return url ? 'video://' + url + '#isVideo=true#' : '';
    }
};
XJ._webHome = function(config, host) {
