function _migratePyRules(index) {
    var oldDirs = ["hiker://files/plugins/chaquopy/libs_py/", "hiker://files/data/chaquopy/libs_py/"];
    var moved = 0;
    for (var i = 0; i < index.length; i++) {
        var r = index[i];
        if (!_isPyRule(r) || !r.url) continue;
        for (var d = 0; d < oldDirs.length; d++) {
            var oldDir = oldDirs[d];
            if (r.url.indexOf(oldDir) === 0) {
                var code = '';
                try { code = readFile(r.url) || ''; } catch (e) { code = ''; }
                if (code) {
                    var newUrl = PY_DIR + r.url.substring(oldDir.length);
                    try {
                        saveFile(newUrl, code);
                        deleteFile(r.url);
                        r.url = newUrl;
                        moved++;
                    } catch (eM) { log('[pyMigrate] 迁移失败 ' + r.url + ': ' + (eM && eM.message ? eM.message : eM)); }
                }
                break;
            }
        }
    }
    if (moved > 0) log('[pyMigrate] 已迁移' + moved + '个Python源规则到 ' + PY_DIR);
    return moved;
}
function getRuleIndex() {
    ensureDir();
    var star = _safeReadJson(RULE_INDEX, []);
    var py = _safeReadJson(PY_INDEX, []);
    var index = star.concat(py);
    var changed = false;
    for (var i = 0; i < star.length; i++) { if (_isPyRule(star[i])) { changed = true; break; } }
    if (!changed) { for (var j = 0; j < py.length; j++) { if (!_isPyRule(py[j])) { changed = true; break; } } }
    if (_migratePyRules(index) > 0) changed = true;
    if (changed) saveRuleIndex(index);
    return index;
}
function saveRuleIndex(index) {
    ensureDir();
