    var star = [];
    var py = [];
    for (var i = 0; i < index.length; i++) {
        if (_isPyRule(index[i])) py.push(index[i]);
        else star.push(index[i]);
    }
    saveFile(RULE_INDEX, JSON.stringify(star));
    saveFile(PY_INDEX, JSON.stringify(py));
}
