function parseListFromRes(res) {
    var data = JSON.parse(res);
    var list = [];
    if (data && data.data) {
        if (Array.isArray(data.data.list)) list = data.data.list;
        else if (data.data.songs) list = data.data.songs;
        else if (data.data.musicList) list = data.data.musicList;
        else if (data.data.tracks) list = data.data.tracks;
        else if (Array.isArray(data.data)) list = data.data;
    }
    return list;
}

