                        if (sTypes) musicUrl += "&_types=" + encodeURIComponent(typeof sTypes === "string" ? sTypes : JSON.stringify(sTypes));
                        var urlRes = fetch(musicUrl, { timeout: 15000 });
                        if (!urlRes || !urlRes.trim()) return "toast://获取播放链接失败:服务未响应";
                        var urlData = JSON.parse(urlRes);
                        var allUrls = [];
                        if (urlData.code === 200 && urlData.data) {
                            var urls = Array.isArray(urlData.data) ? urlData.data : [urlData.data];
                            for (var i = 0; i < urls.length; i++) {
                                var entry = urls[i];
                                if (!entry) continue;
                                var u = "";
                                if (typeof entry === "string") u = entry;
                                else if (typeof entry === "object") {
                                    u = entry.url || entry.musicUrl || entry.src || "";
                                    if (typeof u === "object") u = u.url || u.src || "";
                                }
                                if (u && typeof u === "string") {
                                    if (u.indexOf("/") === 0) u = apiBase + u;
                                    if (u.indexOf("http") === 0) allUrls.push(u);
                                }
                            }
                        }
                        if (!allUrls.length) {
                            if (urlData.code === 404 && urlData.error) return "toast://" + urlData.error;
                            return "toast://获取播放链接失败";
                        }
                        var seen = {}, mp3Urls = [], audioUrls = [], otherUrls = [];
                        for (var i = 0; i < allUrls.length; i++) {
                            var pu = allUrls[i];
                            if (seen[pu]) continue;
                            seen[pu] = 1;
                            if (/\.mp3(\?|$)/i.test(pu)) mp3Urls.push(pu);
                            else if (/\.(m4a|flac|wav|ogg|wma|aac)(\?|$)/i.test(pu)) audioUrls.push(pu);
                            else otherUrls.push(pu);
                        }
                        var sortedUrls = mp3Urls.concat(audioUrls).concat(otherUrls);
                        var urlList = [];
