                            if (sLrcUrl) lyricUrl += "&lrcUrl=" + encodeURIComponent(sLrcUrl);
                            if (sMrcUrl) lyricUrl += "&mrcUrl=" + encodeURIComponent(sMrcUrl);
                            if (sTrcUrl) lyricUrl += "&trcUrl=" + encodeURIComponent(sTrcUrl);
                            var lRes = fetch(lyricUrl, { timeout: 10000 });
                            if (lRes && lRes.trim()) {
                                var lData = JSON.parse(lRes);
                                if (lData.data) {
                                    if (typeof lData.data === "string") lyricText = lData.data;
                                    else if (lData.data.lyric) lyricText = typeof lData.data.lyric === "string" ? lData.data.lyric : "";
                                    else if (lData.data.lrc) lyricText = typeof lData.data.lrc === "string" ? lData.data.lrc : "";
                                    else if (lData.data.info) {
                                        var info = lData.data.info;
                                        if (info.lrc) lyricText = typeof info.lrc === "string" ? info.lrc : "";
