function pickApi() {
    var cached = getItem('apiCache');
    if (cached) return cached;
    var alive = "";
    var dead = 0;
    // 最多容忍 2 条死线就收工：冷启动不能被死域名拖到几十秒
    for (var i = 0; i < ONE_APIS.length && dead < 2; i++) {
        try {
            var res = pdfh(fetch(ONE_APIS[i], { timeout: 4000 }), 'body&&Text');
            if (res === "OK") return ONE_APIS[i];
            if (!alive && res) alive = ONE_APIS[i];
        } catch (e) { dead++; log('探测 ' + ONE_APIS[i] + ' 失败') }
    }
    return alive || ONE_APIS[0];
}

// 域名探活：CDN 根目录 403 也算活（只看连没连上，要求 200 会永远选不到）
function probeDomain(list, path) {
    // 只试前两条、短超时：探不通就直接用列表第一条兜底，别把首屏拖死
    for (var i = 0; i < list.length && i < 2; i++) {
        try {
            var probe = JSON.parse(fetch(list[i] + (path || ''), { withStatusCode: true, timeout: 3500 }));
            if (probe.statusCode > 0) return list[i];
        } catch (e) { log('域名探测失败 ' + list[i]) }
    }
    return "";
}

function bootstrapEnv(force) {
    try {
        var host = force ? pickApi() : getItem('api');
        if (!host) host = getItem('api') || getItem('apiCache') || pickApi() || ONE_APIS[0];
        setItem('api', host);
