  pics: function(){
    var d = [], page = 1;
    try{ if(typeof MY_PAGE !== 'undefined' && MY_PAGE) page = parseInt(MY_PAGE) || 1; }catch(e){}
    try{
      if(MY_URL){
        var mp = ('' + MY_URL).match(/[?&]page=(\d+)/);
        if(mp) page = parseInt(mp[1]) || 1;
      }
    }catch(e){}
    if(!(page > 0)) page = 1;

    var info = {};
    try{ info = JSON.parse(getMyVar('crdj_comic_read', '') || '{}'); }catch(e){}
    var eps = info.eps || [];
    var curN = parseInt(info.n, 10) || 1;
    // 下滑：第 page 页对应从当前话开始的第 page 话
    var targetIdx = -1;
    for(var i = 0; i < eps.length; i++){
      if(parseInt(eps[i].n, 10) === curN){ targetIdx = i; break; }
    }
    if(targetIdx < 0) targetIdx = 0;
    var idx = targetIdx + (page - 1);
    if(idx >= eps.length){
      if(page === 1) d.push({ title: '没有图片', url: 'hiker://empty', col_type: 'text_center_1' });
      else d.push({ title: '已经到底了', url: 'hiker://empty', col_type: 'text_center_1' });
      setResult(d);
      return;
    }

    var ep = eps[idx];
    var host = info.host || this.host;
    var html = this.get(ep.url);
    var imgs = [], m, re;
    re = /data-src="(https?:\/\/[^"]+)"/gi;
    while((m = re.exec(html))){
      var src = (m[1] + '').replace(/&amp;/g, '&');
      if(/logo|icon|yandex|google|gif;base64|poster/i.test(src)) continue;
      if(imgs.indexOf(src) < 0) imgs.push(src);
    }
    if(!imgs.length){
      re = /src="(https?:\/\/pic\.[^"]+)"/gi;
      while((m = re.exec(html))){
        var s2 = (m[1] + '').replace(/&amp;/g, '&');
        if(imgs.indexOf(s2) < 0) imgs.push(s2);
      }
    }

    if(page === 1 || imgs.length){
      d.push({
        title: (info.title ? info.title + ' · ' : '') + '第' + ep.n + '话',
        url: 'hiker://empty',
        col_type: 'text_1'
      });
    }
    if(!imgs.length){
      d.push({ title: '本话暂无图片', url: 'hiker://empty', col_type: 'text_center_1' });
    }else{
      for(var j = 0; j < imgs.length; j++){
