function clickDownload(item, info, MY_ID, i) {
    let loadingTeam = JSON.parse(getMyVar(MY_ID + ":loadingTeam", "[]") || "[]");
    let ElementIndex = loadingTeam.indexOf(i);
    if (ElementIndex > -1) return "toast://正在下载";

    loadingTeam.push(i);
    putMyVar(MY_ID + ":loadingTeam", JSON.stringify(loadingTeam));
    updateItem({
        title: "‘‘" + item.title + "’’",
        extra: {
            id: MY_ID + "#" + i
        }
    });
    let result = "toast://下载失败";
    try {
        toast("开始下载:" + item.title);
        let download = $.require("hiker://page/Download.exe.js");
        result = download(item, info, i, MY_ID);
        updateItem({
            title: "““" + item.title + "””",
            url: "toast://已下载",
            extra: {
                id: MY_ID + "#" + i
            }
        });
    } catch (e) {
        updateItem({
            title: item.title,
            extra: {
                id: MY_ID + "#" + i
            }
        });
        log(e.toString());
    } finally {
        loadingTeam.splice(ElementIndex, 1);
        putMyVar(MY_ID + ":loadingTeam", JSON.stringify(loadingTeam));
    }
    return result;
}

