const templateCache = {
    get(pageType) {
        return getVar(`cache_${pageType}`);
    },
    set(pageType, templateName) {
        putVar(`cache_${pageType}`, templateName);
    },
    clear(pageType) {
        putVar(`cache_${pageType}`, '');
    }
};

// 1. 定义一级页面规则
const primaryRules = {
    "stui-vodlist": {
        list: ".stui-vodlist&&li",
        title: "a&&title",
        desc: ".pic-text&&Text",
        img: ".lazyload||a&&data-original",
        url: "a&&href"
    },
    "myui-vodlist": {
        list: ".myui-vodlist&&li",
