        img: ".lazyload&&data-original",
        url: "a&&href"
    },
    "pack-ykpack": {
        list: "body&&.pack-ykpack",
        title: "a&&title",
        desc: "span,-1&&Text",
        img: ".eclazy&&data-original",
        url: "a&&href"
    },
    "module-items": {
        list: "body&&.module-item",
        title: "strong||a&&Text||title",
        desc: ".module-item-text||.module-item-note&&Text",
        img: "img||.lazy&&data-src||data-original||src",
