// 创建缓存管理器
const templateCache = {
    get: () => {
        const cacheKey = `template_${md5(MY_HOME)}`;
        return getMyVar(cacheKey);
    },
    set: (templateName) => {
        const cacheKey = `template_${md5(MY_HOME)}`;
        putMyVar(cacheKey, templateName);
        log(`缓存模板: ${templateName} for ${MY_HOME}`);
    },
    clear: () => {
        const cacheKey = `template_${md5(MY_HOME)}`;
        removeMyVar(cacheKey);
        log(`清除模板缓存: ${MY_HOME}`);
    }
};

const autoSecondaryPage = (htmlsrc, lazy) => {
    if (typeof lazy === 'undefined') lazy = "";
    const htmlSource = htmlsrc;
    
    // 尝试从缓存获取模板
    const cachedTemplate = templateCache.get();
    if (cachedTemplate && secondaryTemplates[cachedTemplate]) {
        log(`使用缓存模板: ${cachedTemplate}`);
        try {
            let config = secondaryTemplates[cachedTemplate];
            if (processTemplate(config, htmlSource, lazy)) {
                return;
            } else {
                templateCache.clear();
            }
        } catch (e) {
            log(`缓存模板处理失败: ${e.message}`);
            templateCache.clear();
        }
    }
    
    // 没有缓存或缓存无效，开始匹配模板
    for (var templateName in secondaryTemplates) {
        log(`尝试模板: ${templateName}`);
        try {
            let config = secondaryTemplates[templateName];
            if (processTemplate(config, htmlSource, lazy)) {
                // 匹配成功，缓存模板名称
                templateCache.set(templateName);
                return;
            }
        } catch (e) {
            log("尝试二级模板 " + templateName + " 失败: " + e.message);
        }
    }
    
    log("没有匹配到任何二级模板");
    setResult([]);
}

// 提取模板处理逻辑到单独函数
const processTemplate = (config, htmlSource, lazy) => {
    // 获取线路元素
    var items = pdfa(htmlSource, config.线路);
    log(`找到线路数量: ${items.length}`);
    
    if (items.length > 0) {  
        // 处理线路和选集
        var result = processLinesAndEpisodes(
            htmlSource, 
            config.线路, 
            config.线路名, 
            config.选集, 
            config.选集列表,
            config.排除
        );
        var tabs = result.tabs;
        var lists = result.lists;
        
     //   log(`解析得到线路名: ${tabs.join(", ")}`);
        
        // 检查线路名是否包含无效关键词
        if (tabs.length > 0) {
            const excludeKeywords = ["主演", "类型", "年份", "地区", "语言", "导演", "更新", "状态", "年代"];
            let hasInvalidLineName = tabs.some(tabName => 
                excludeKeywords.some(keyword => tabName.includes(keyword))
            );
            
            if (hasInvalidLineName) {
                log(`线路名包含无效关键词: ${tabs.join(", ")}`);
                throw new Error(`线路名包含无效关键词: ${tabs.join(", ")}`);
            }
        } else {
            log("没有解析到有效的线路名");
        }
        
        // 检查整个模板是否有有效选集
        let hasValidList = false;
        for (let i = 0; i < lists.length; i++) {
            if (lists[i] && lists[i].length > 0) {
                hasValidList = true;
                break;
            }
        }
        
        // 如果整个模板都没有有效选集，跳过这个模板
        if (!hasValidList) {
            log("所有线路的选集列表都为空");
            throw new Error("整个模板的选集列表都为空");
        }
        
     //   log("模板有效性检查通过，开始创建详情页...");

        // 创建详情项
        var d = [{
            title: ($.type(config.title) === 'function' ? config.title(htmlSource) : pdfh(htmlSource, config.title)) || '未获取到标题',
            desc: pdfh(htmlSource, config.desc) || '无',
            img: pd(htmlSource, config.img) || "",
            url: MY_URL,
            col_type: config.col_type || "movie_1"
        }]; 
        
        // 确保lists被正确存储
        storage0.putMyVar("lists", lists);
    
        // 添加排序按钮
        d.push(createSortButton(MY_URL, tabs, lists, d[0], lazy));
        
        // 添加线路切换按钮
        if (tabs.length > 0) {
            var lineButtons = createLineButtons(MY_URL, tabs, lists, lazy);
            for (var i = 0; i < lineButtons.length; i++) {
                d.push(lineButtons[i]);
            }
        }
        
        // 添加选集列表
        var episodes = createEpisodeList(MY_URL, lists, lazy);
        for (var j = 0; j < episodes.length; j++) {
            d.push(episodes[j]);
        }
        
        // 设置更新集数规则
        setLastEpisodeRule(config.选集, config.选集列表);
        
        // 添加底部空白块
        d.push(createFooterBlock(MY_URL));
        
        setResult(d);
        log("匹配二级模板成功");
        return true;
    }
    return false;
}


const createLineButtons = (MY_URL, tabs, lists, lazy) => {
    // 获取当前线路并确保有效
    let currentLine = parseInt(getMyVar(MY_URL, '0')) || 0;
    currentLine = Math.min(currentLine, tabs.length - 1);
    
    return tabs.map((tabName, id) => ({
        title: currentLine == id ? `““${tabName}””` : tabName,
        url: $("#noLoading#").lazyRule((线路列表, lazy, id, MY_URL) => {
            const lists = storage0.getMyVar("lists");
            // 确保线路ID有效
            const validId = Math.min(id, lists.length - 1);
            
            if (!lists[validId] || lists[validId].length === 0) {
                log(`选集列表不存在或为空，线路ID: ${validId}`);
                // 显示错误提示但不中断操作
                updateItem({
                    title: `““${tabName}(无选集)””`,
                    extra: { id: `${MY_URL}_线路${validId}` }
                });
                return "hiker://empty";
            }
            
            // 更新所有线路按钮状态
            线路列表.forEach((name, xid) => {
                try {
                    updateItem({
                        title: validId == xid ? `““${name}””` : name,
                        extra: { id: `${MY_URL}_线路${xid}` }
                    });
                } catch (e) {
                    log("更新线路按钮错误: " + e.message);
                }
            });
            
            putMyVar(MY_URL, validId.toString());
            let chapters = lists[validId];
            
            // 检查排序状态
            const sortOrder = getMyVar(MY_URL + "章节排序", '#1aad19">正序');
            if (sortOrder == '#FF0000">倒序') {
                chapters = chapters.slice().reverse();
            }
            
            // 生成选集项
            let chapterItems = chapters.map(data => ({
                title: pdfh(data, 'a&&Text'),
                url: pd(data, 'a&&href') + lazy,
                col_type: chapters.length > 3 ? 'text_4' : 'text_2',
                extra: { 
                    cls: MY_URL + "_选集", 
                    id: pd(data, 'a&&href') 
                }
            }));
            
            // 先删除旧选集 - 修复了这里的try-catch语法错误
            try {
                deleteItemByCls(MY_URL + "_选集");
            } catch (e) {
                log("删除旧选集错误: " + e.message);
            }
            
            // 添加新选集
            try {
                addItemBefore(MY_URL + "footer", chapterItems);
            } catch (e) {
                log("添加选集错误: " + e.message);
            }
            
            return "hiker://empty";
        }, tabs, lazy, id, MY_URL),
        col_type: 'flex_button',
        extra: { id: `${MY_URL}_线路${id}` }
    }));
}

// 优化选集匹配逻辑
const processLinesAndEpisodes = (html, 线路, 线路名, 选集, 选集列表, 排除) => {
    // 获取线路标签
    const lineElements = pdfa(html, 线路);
  //  log(`找到线路元素数量: ${lineElements.length}`);
    
    const tabs = [];
    const lists = [];
    
    // 提取有效的线路名
    for (let i = 0; i < lineElements.length; i++) {
        let tabText = pdfh(lineElements[i], 线路名);
        if (tabText) {
            tabs.push((typeof 排除 !== 'undefined' && 排除) ? 
                tabText.replace(new RegExp(排除, "g"), "") : 
                tabText);
        }
    }
    
    // 获取所有选集区域
    const allEpisodeSections = pdfa(html, 选集);
  //  log(`找到选集区域数量: ${allEpisodeSections.length}`);
    
    // 提取有效的选集列表
    for (let i = 0; i < lineElements.length; i++) {
        let episodes = [];
        
        // 尝试按顺序匹配选集区域
        if (i < allEpisodeSections.length) {
            episodes = pdfa(allEpisodeSections[i], 选集列表);
        }
        
        // 如果按顺序未找到，尝试通过ID匹配
        if (episodes.length === 0) {
            const lineId = pdfh(lineElements[i], 'a&&id') || 
                          pdfh(lineElements[i], 'a&&data-id') ||
                          pdfh(lineElements[i], 'div&&id') || 
                          pdfh(lineElements[i], 'div&&data-id');
            
            if (lineId) {
                const matchedSection = allEpisodeSections.find(section => 
                    pdfh(section, 'div&&id') === lineId || 
                    pdfh(section, 'div&&data-id') === lineId
                );
                
                if (matchedSection) {
                    episodes = pdfa(matchedSection, 选集列表);
                }
            }
        }
        
        // 如果仍未找到，尝试全局匹配
        if (episodes.length === 0) {
            episodes = pdfa(html, 选集列表);
        }
        
        lists.push(episodes);
    //    log(`线路 ${i+1} 找到选集数量: ${episodes.length}`);
    }
    
    // 添加清理监听器
    addListener("onClose", $.toString(() => {
        clearMyVar("lists");
    }));
    
    // 存储选集列表
    storage0.putMyVar("lists", lists);
    
    return { tabs, lists };
}

