            }
            
            // 保存新的排序状态
            putMyVar(MY_URL + "章节排序", newLabel);
            return "hiker://empty";
        }, tabs, lazy, d[0], TV推送, MY_URL),
        col_type: 'flex_button',
        extra: { 
            id: MY_URL + "_排序",
            longClick: [{ title: "TVbox推送", js: TV推送(tabs, lists, d[0]) }] 
        }
    };
}

const createEpisodeList = (MY_URL, lists, lazy) => {
    let currentLine = parseInt(getMyVar(MY_URL, '0')) || 0;
    
    // 确保当前线路有效
    currentLine = Math.min(currentLine, lists.length - 1);
